import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-d2-001","clusterId":"D","werkstueckRef":"D.3.3","stufe":1,"question":"Wie ist das Verhalten des Teamleiters einzuordnen, und woran erkennst du es?","options":["Er stellt systematisch ihre Erinnerung und Wahrnehmung infrage, bis sie an sich selbst zweifelt. Das ist ein Angriff auf ihre Fähigkeit zu wissen, was wahr ist.","Er wertet sie vor dem Team systematisch ab, bis sie sich nicht mehr zu widersprechen traut. Das ist ein Angriff auf ihr Ansehen und ihren Platz in der Gruppe.","Er erinnert sich tatsächlich anders und besteht wiederholt auf seiner Fassung, bis sie nachgibt. Das ist ein ehrlicher Streit um Erinnerungen und kein Angriff auf sie.","Er bestreitet in diesem einen Meeting eine Zusage, um sich einen Vorteil zu verschaffen. Dass sie danach an sich zweifelt, ist nur ein Nebeneffekt dieses Einzelfalls."],"correctIndex":0,"explanation":"Entscheidend ist das Muster, nicht die einzelne Lüge: Er leugnet Geschehenes, bestreitet ihre Erinnerung („Du erinnerst dich falsch“) und wertet ihre Einschätzung ab („überempfindlich“), und das wiederholt über Wochen. Die Folgen passen dazu: Sie zweifelt an sich selbst, fragt andere, ob sie sich alles einbildet, und entschuldigt sich ständig. Das nennt man Gaslighting, nach dem Theaterstück „Gas Light“ (1938), in dem ein Ehemann seiner Frau einredet, sie bilde sich das schwächer werdende Gaslicht nur ein. Gaslighting zielt darauf, dass jemand der eigenen Wahrnehmung nicht mehr traut. Schriftliche Notizen helfen dagegen, weil sie sich nicht wegleugnen lassen. Systematisches Abwerten kann Menschen verunsichern, hier geht es aber um das Leugnen von Geschehenem und das Bestreiten ihrer Erinnerung, nicht um den Verlust von Ansehen. Ein ehrlicher Erinnerungsstreit wäre es nicht: Ihre schriftliche Notiz liegt vor, und die Abwertung als „überempfindlich“ gehört nicht zu einem ehrlichen Streit. Eine einzelne Lüge im Streit wäre zudem kein Muster, das sich über Wochen wiederholt.","coreRule":"⚡ Gaslighting ist nicht eine Lüge, sondern ein System: Es zielt darauf, dass du deiner eigenen Wahrnehmung nicht mehr traust.","beleg":"Werkstück D.3.3 (Kernidee, Kontext & Tiefe); Fn. gl-d-gaslight (Hamilton, „Gas Light“, Uraufführung 5. Dezember 1938, Richmond Theatre; MGM-Verfilmung 1944)","status":"entwurf","scenario":"Ein Teamleiter sagt im Meeting: „Das habe ich nie gesagt.“ Eine Mitarbeiterin hat die Zusage am Vortag schriftlich notiert und widerspricht. Er antwortet: „Du erinnerst dich falsch. Du bist in letzter Zeit ohnehin überempfindlich.“ Das passiert seit Wochen immer wieder. Inzwischen fragt sie Kollegen, ob sie sich wohl alles nur einbildet, und entschuldigt sich ständig bei ihm.","quote":"","quoteLabel":"","kurz":"Entscheidend ist das Muster über Wochen: Er leugnet Geschehenes und erklärt ihre Erinnerung für falsch. Die Folge ist, dass sie ihrer Wahrnehmung nicht mehr traut. Eine einzelne Lüge erklärt das nicht, ein Muster schon.","prueffrage":"Was hat die Mitarbeiterin schriftlich, was entgegnet er darauf, und wie oft geht das schon so?","rueckmeldung":[{"option":1,"text":"Abwertung kann tatsächlich verunsichern, und „überempfindlich“ gehört dazu. Hier zielt sie aber darauf, ihre Wahrnehmung zu entwerten, und das Leugnen von Geschehenem fehlt in dieser Deutung. Ihre Folgen sind Selbstzweifel, nicht der Verlust von Ansehen."},{"option":2,"text":"Einen ehrlichen Streit um Erinnerungen gibt es, aber er sähe anders aus. Hier liegt ihre Notiz vom Vortag vor, und „überempfindlich“ ist keine Erinnerungsfrage, sondern eine Abwertung. Dazu kommt, dass es sich seit Wochen wiederholt."},{"option":3,"text":"Für einen Einzelfall spricht, dass die Zusage in diesem Meeting bestritten wird. Das Szenario nennt aber weder einen Vorteil noch einen einmaligen Vorfall, sondern ein Muster über Wochen. Ihre Selbstzweifel und Entschuldigungen sind Teil davon, kein Nebeneffekt."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnsen, R. E. (2017): On the Origins of „Gaslighting“. Los Angeles Review of Books, 09.03.2017","oeffentlich":true,"url":"https://lareviewofbooks.org/article/on-the-origins-of-gaslighting/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"131034b67f8e2732"}},{"id":"qx-d2-002","clusterId":"D","werkstueckRef":"D.3.3","stufe":2,"question":"Welcher Schritt hilft dir am besten, wieder festen Boden unter den Füßen zu bekommen?","scenario":"Eine Kollegin sagt dir immer wieder: „So war das nie“, „Du erinnerst dich falsch“, „Du bist gerade so empfindlich“. Du merkst, dass du dir selbst nicht mehr sicher bist, ob deine Erinnerung an die Gespräche stimmt.","options":["Du lässt die Kollegin ihre Version erklären, damit ihr euch gemeinsam auf eine Fassung der Gespräche einigt.","Du hältst Gespräche und Ereignisse zeitnah schriftlich fest, damit du später auf etwas Überprüfbares zurückgreifst.","Du fragst mehrere Bekannte, welche Version glaubwürdiger klingt, und richtest dich nach dem Urteil der Mehrheit.","Du gehst die Gespräche abends in Gedanken noch einmal durch, damit deine Erinnerung klar bleibt und du sicherer wirst."],"correctIndex":1,"explanation":"Wenn jemand systematisch bestreitet, was du erlebt hast, steht Aussage gegen Aussage, und deine eigene Wahrnehmung wirkt zunehmend unsicher. Ein geschriebenes Protokoll ist eine Waffe gegen das Leugnen der Vergangenheit: Mit Notizen zu Gesprächen und Ereignissen kannst du nachlesen, was war, statt nur im Kopf zu grübeln. Hilfreich ist die Frage: Was habe ich selbst gesehen und gehört?","coreRule":"⚡ Schreib auf, was geschieht: Ein Protokoll lässt sich nicht wegleugnen.","quote":"","quoteLabel":"","beleg":"Werkstück D.3.3 (Anti-Denkmuster, Aktivierungs-Frage und Logbuch)","status":"entwurf","kurz":"Wo Aussage gegen Aussage steht, hilft nur etwas Festes: Zeitnahe Notizen lassen dich nachlesen, was war, statt nur im Kopf zu grübeln. Der naheliegende Fehler ist, die Klärung bei anderen oder im Gedächtnis zu suchen, obwohl dort nichts Überprüfbares entsteht.","prueffrage":"Worauf stützt sich bisher deine Erinnerung an die Gespräche, und worauf die Version der Kollegin?","rueckmeldung":[{"option":0,"text":"Sich auszutauschen wirkt reif und versöhnlich. Doch gerade sie bestreitet die Gespräche, daher entstünde aus einer „gemeinsamen Fassung“ keine überprüfbare Grundlage, sondern vermutlich nur ein Kompromiss über etwas, das unklar bleibt."},{"option":2,"text":"Eine Außenperspektive kann entlasten. Die Bekannten waren aber nicht dabei und können nichts überprüfen; entscheiden würden dann Sympathie oder Mehrheit statt eines Belegs dafür, was tatsächlich gesagt wurde."},{"option":3,"text":"Gedankliches Durchgehen fühlt sich nach Klarheit an. Es ruft die Erinnerung aber nur erneut ab und schafft nichts Festes, auf das du dich später stützen könntest; leicht wird daraus bloßes Grübeln."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"125907e453467225"}},{"id":"qx-d2-003","clusterId":"D","werkstueckRef":"D.3.3","stufe":3,"question":"Eine Kollegin sagt dir mehrfach hintereinander: „Das habe ich nie gesagt“, obwohl du eine Mail von ihr hast, in der es steht. Als du darauf hinweist, meint sie: „Du bist in letzter Zeit so überempfindlich.“ Eine Bekannte rät dir: „Sei nicht so streng mit ihr. Ein bisschen Leugnen und Umdeuten ist in jedem Konflikt normal und hat auch seine nützliche Seite.“ Was ist an diesem Rat falsch?","options":["Er stützt sich nur auf das Gewicht, das die Bekannte als Vertraute hat, und ersetzt damit eine nachvollziehbare Begründung durch bloßen Rang, obwohl die Mail als Beleg vorliegt.","Er übersieht, dass Leugnen belegter Tatsachen und Umdeuten der Wahrnehmung als Muster das Vertrauen in die eigene Erinnerung untergraben und keine harmlose, nützliche Seite haben.","Er unterstellt der Kollegin eine böse Absicht, obwohl niemand weiß, warum sie die Mail abstreitet und dich überempfindlich nennt, und urteilt damit vorschnell über ihre Motive.","Er schließt aus diesem einen Gespräch voreilig auf ihren Charakter, obwohl ein einzelner Vorfall wenig darüber sagt, wie sie sonst handelt."],"correctIndex":1,"explanation":"Wer Dinge leugnet, die belegt sind (hier die Mail), und die Wahrnehmung des Gegenübers als „überempfindlich“ abtut, greift dessen Vertrauen in die eigene Erinnerung an; geschieht das wiederholt, spricht man von Gaslighting, nach dem Theaterstück „Gas Light“ von 1938. Dieses Muster hat keine harmlose oder nützliche Seite, denn es läuft darauf hinaus, dass das Gegenüber an der eigenen Wahrnehmung zweifelt, ob es nun bewusst oder unbewusst eingesetzt wird. Der Rat, das als normalen Konflikt hinzunehmen, ist deshalb ein Fehlschluss. Sinnvoller ist es, die eigene Wahrnehmung zu sichern, etwa mit Notizen und Belegen wie der Mail.","coreRule":"⚡ Gaslighting hat keine harmlose Dosis: Wer belegte Tatsachen leugnet und deine Wahrnehmung für unzuverlässig erklärt, schadet von Anfang an, egal ob mit Absicht oder ohne.","beleg":"Werkstück D.3.3 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Belegte Tatsachen zu leugnen und die Wahrnehmung des Gegenübers als „überempfindlich“ abzutun, untergräbt als wiederkehrendes Muster das Vertrauen in die eigene Erinnerung. Wer das als normalen Konflikt abtut, übersieht, dass es keine nützliche Seite hat.","prueffrage":"Was steht in der Mail, was sagt die Kollegin dazu, und wie sicher wärst du dir nach dem dritten Mal noch?","rueckmeldung":[{"option":0,"text":"Dass die Mail als Beleg vorliegt, stimmt, und gerade deshalb ist es sinnvoll, sie zu sichern. Die Bekannte beruft sich aber auf keinen Rang, sie behauptet nur, Leugnen sei normal. Der Fehler liegt in dieser Verharmlosung."},{"option":2,"text":"Die Gründe der Kollegin kennt tatsächlich niemand. Der Rat unterstellt ihr aber keine böse Absicht, er rät sogar zur Nachsicht. Sein Fehler ist, ein Muster zu verharmlosen, das unabhängig von der Absicht wirkt."},{"option":3,"text":"Ein einzelner Vorfall sagt wenig über einen Charakter, aber hier geht es um keinen: Das Leugnen kam mehrfach hintereinander vor. Der Rat schließt auch nichts auf den Charakter, er redet das Muster klein."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnsen, R. E. (2017): On the Origins of „Gaslighting“. Los Angeles Review of Books, 09.03.2017","oeffentlich":true,"url":"https://lareviewofbooks.org/article/on-the-origins-of-gaslighting/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3a325524a1623cc1"}},{"id":"qx-d2-004","clusterId":"D","werkstueckRef":"D.3.3","stufe":4,"question":"Warum ist dieses Vorgehen mehr als bloßes Überzeugen und eine Form von Gaslighting?","scenario":"Eine neue Bekannte nimmt dich zu einem Treffen ihrer Gruppe mit. Dort sagt ein Sprecher zu einem Neuling: „Dein früheres Denken war falsch und gehirngewaschen. Nur wir sagen dir, was wirklich wahr ist.“ Alles von außen, ob von Familie, Wissenschaftlern oder „Systemmedien“, gilt in der Gruppe als Lüge. Ein Mitglied erzählt dir später: „Früher habe ich selbst viel gezweifelt, aber heute weiß ich, dass ich mir nur noch von der Gruppe sagen lassen darf, was stimmt.“","options":["Die Gruppe erklärt sich zur einzigen Quelle der Wahrheit und bringt Mitglieder dazu, ihrem eigenen früheren Urteil zu misstrauen.","Die Gruppe übt Gruppenzwang aus: Wer wie das Mitglied früher gezweifelt hat, wird bloßgestellt und riskiert den Ausschluss.","Die Gruppe wirbt Neue mit großen Versprechen an, die sich später als übertrieben herausstellen, und enttäuscht so ihr Vertrauen.","Die Gruppe überschüttet Neue, wie den Neuling beim Treffen, mit Zuwendung, sodass sie sich der Gemeinschaft verpflichtet fühlen."],"correctIndex":0,"explanation":"Entscheidend ist, was mit dem Urteilsvermögen der Person passiert. Gaslighting zielt darauf ab, dass jemand der eigenen Wahrnehmung, Erinnerung und Urteilskraft nicht mehr traut und nur noch glaubt, was der Manipulator sagt. Hier geschieht genau das: Das frühere Denken wird pauschal als „gehirngewaschen“ entwertet, alles Äußere als Täuschung gebrandmarkt, und die Gruppe setzt sich als einzige Wahrheitsquelle. Das isoliert von Familie, Wissenschaft und Medien und macht abhängig von der Einschätzung der Gruppe. Gute Überzeugungsarbeit würde dagegen Gründe nennen, die man selbst prüfen kann, und das eigene Urteil der Person stärken statt ersetzen. Gruppenzwang wirkt über Angst vor Ausschluss, nicht über Zweifel am eigenen Urteil, und davon ist hier keine Rede. Übertriebene Versprechen enttäuschen, machen aber niemanden unsicher, ob er sich auf sein Urteil verlassen kann. Und herzliche Aufnahme bindet über Zuwendung, nicht dadurch, dass das eigene Denken entwertet wird.","coreRule":"⚡ Wer dir sagt, nur er kenne die Wahrheit und dein früheres Denken sei wertlos, will nicht überzeugen, sondern dein Urteil ersetzen.","beleg":"Werkstück D.3.3 (Anwendung & Relevanz, „In Kulten und Verschwörungsmythen“; Verbindungen)","status":"entwurf","kurz":"Hier wird das Urteilsvermögen selbst angegriffen: Das frühere Denken gilt pauschal als „gehirngewaschen“, alles Äußere als Lüge, und die Gruppe wird zur einzigen Wahrheitsquelle. Gute Überzeugung nennt prüfbare Gründe und stärkt das eigene Urteil.","prueffrage":"Bekommst du Gründe genannt, die du selbst nachprüfen kannst, oder nur die Auskunft, wem du glauben darfst?","rueckmeldung":[{"option":1,"text":"Gruppenzwang ist ein verbreiteter Mechanismus, doch im Szenario ist von Bloßstellung oder Ausschluss nichts zu lesen. Zwang wirkt über Angst vor Folgen; hier geht es darum, dass jemand dem eigenen Urteil nicht mehr traut."},{"option":2,"text":"Große Versprechen, die sich später als übertrieben erweisen, sind eine Täuschung, die Vertrauen enttäuscht. Im Szenario kommen sie aber nicht vor, und sie erklären auch nicht, warum jemand an seinem eigenen Urteil zweifelt."},{"option":3,"text":"Herzliche Aufnahme kann tatsächlich binden. Im Szenario wird der Neuling aber nicht umworben, sondern sein früheres Denken wird abgewertet. Zuwendung bindet über Zugehörigkeit, nicht über Misstrauen in das eigene Urteil."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bc0d9a2b87919c40"}},{"id":"qx-d2-005","clusterId":"D","werkstueckRef":"D.3.4","stufe":1,"question":"Was ist an dieser Reaktion des Vaters als Gesprächsbeitrag das Hauptproblem?","scenario":"Beim Abendessen erzählst du, was du im Seminar über strukturelle Ursachen von Armut gelernt hast: Bildungschancen, soziale Herkunft, Benachteiligung. Dein Vater winkt ab und sagt in einem Ton, der keine Widerrede zulässt: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“","options":["Er beantwortet eine vielschichtige Frage mit einer endgültig klingenden Allerweltsweisheit und beendet so das Gespräch, ohne auf deine Argumente einzugehen.","Er widerlegt deine Argumente mit einem bewährten Sprichwort, denn gesammelte Lebenserfahrung wiegt schwerer als eine Seminarthese.","Er verlangt von dir den Beweis, dass es strukturelle Armutsursachen gibt, und verschiebt damit die Beweislast auf deine Seite.","Er stellt deine Position verzerrt als Ausrede für Untätigkeit dar und widerlegt dann nur diese zugespitzte Version."],"correctIndex":0,"explanation":"Der Satz klingt weise und endgültig, geht aber auf keines deiner Argumente ein. Er ersetzt die Auseinandersetzung durch eine Formel und signalisiert: Das Thema ist für mich erledigt, und du brauchst auch nicht weiter nachzudenken. Ob das Sprichwort im Kern etwas Wahres trifft, ist dafür unerheblich. Entscheidend ist seine Funktion im Gespräch: Es soll die Diskussion beenden, nicht klären. Eine gute Antwort darauf ist, das Klischee „auszupacken“ und zu fragen, wie die Phrase bei den konkreten Details dieses Problems weiterhilft.","coreRule":"⚡ Ein Satz, der eine Frage beendet, statt sie zu beantworten, ist ein Rollladen und kein Argument.","quote":"Sie hat die komplexe, nuancierte Debatte nicht widerlegt, sondern sie einfach kurzgeschlossen.","quoteLabel":"Merksatz:","beleg":"Werkstück D.3.4 (Das Gespräch am Familientisch; Kernidee)","status":"entwurf","kurz":"Der Satz klingt weise und endgültig, geht aber auf kein einziges Argument ein. Statt zu klären, beendet er das Gespräch. Ob im Sprichwort etwas Wahres steckt, ist dafür unerheblich: Entscheidend ist, was er im Gespräch bewirkt.","prueffrage":"Wie könnte das Gespräch nach diesem Satz sinnvoll weitergehen, und was hat der Vater dafür angeboten?","rueckmeldung":[{"option":1,"text":"Lebenserfahrung kann ein wertvoller Hinweis sein, und Sprichwörter fassen oft Erfahrungen zusammen. Hier wird aber nichts widerlegt: Auf keines deiner Argumente wird eingegangen, und ein Sprichwort ersetzt keinen Beleg."},{"option":2,"text":"Das Muster gibt es, die Beweislast lässt sich geschickt verschieben. Der Vater verlangt hier aber gar keinen Beweis. Er stellt auch keine Gegenfrage, sondern winkt ab und sagt einen einzigen Satz."},{"option":3,"text":"Ein Strohmann gibt die Gegenposition verzerrt wieder, um sie leichter anzugreifen. Dein Vater gibt deine Position aber gar nicht wieder, weder verzerrt noch zugespitzt: Er geht auf sie überhaupt nicht ein."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism: A Study of „Brainwashing“ in China. Kap. 22 „Ideological Totalism“, Abschnitt „Loading the Language“ (Nachdruck Chapel Hill: University of North Carolina Press 1989)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"49ed486608838e36"}},{"id":"qx-d2-006","clusterId":"D","werkstueckRef":"D.3.4","stufe":2,"question":"Welche Reaktion bringt das Gespräch am besten wieder auf die Sache?","scenario":"Du kritisierst eine angebliche Heilmethode und fragst, welche Belege es für ihre Wirkung gibt. Dein Gegenüber antwortet nur: „Vertraue einfach dem Prozess.“","options":["Mit dem Spruch „Vertrauen ist gut, Kontrolle ist besser“ antworten, damit beide Seiten gleich stark dastehen.","Nachfragen, was diese Phrase im vorliegenden Fall konkret leistet und woran man erkennen würde, dass die Methode wirkt.","Fragen, ob die Person selbst an der Heilmethode verdient, weil finanzielle Interessen die Glaubwürdigkeit der Aussage beeinflussen können.","Der Person zustimmen, dass Vertrauen wichtig ist, und sie fragen, welche Erfahrungen sie selbst mit der Heilmethode gemacht hat."],"correctIndex":1,"explanation":"„Vertraue einfach dem Prozess“ beantwortet deine Frage nach Belegen nicht, sondern beendet sie. Hilfreich ist, die Phrase auf den konkreten Fall anzuwenden: Was genau soll hier geschehen, und woran würde man merken, dass die Methode wirkt oder nicht wirkt? So wird aus der Floskel wieder eine prüfbare Behauptung. Ein Gegenspruch bleibt selbst eine Floskel und klärt in der Sache nichts. Die Frage nach finanziellen Interessen kann berechtigt sein, beantwortet aber nicht, ob die Methode wirkt. Und die Frage nach persönlichen Erfahrungen klingt zugewandt, liefert aber nur Einzelberichte statt Belege.","coreRule":"⚡ Packe die Floskel aus: Frag, was sie im konkreten Fall tatsächlich leistet.","beleg":"Werkstück D.3.4 (Anwendung & Relevanz, Esoterik & New Age: „Vertraue einfach dem Prozess“; Das Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"Die Phrase beendet deine Frage nach Belegen, statt sie zu beantworten. Am besten wendest du sie auf den konkreten Fall an: Was soll geschehen, und woran würde man merken, dass die Methode wirkt? So wird aus der Floskel wieder eine prüfbare Behauptung.","prueffrage":"Was weißt du nach dieser Antwort mehr über die Wirkung der Methode als vorher?","rueckmeldung":[{"option":0,"text":"Ein Gegenspruch wirkt wie Ausgleich, bleibt aber selbst eine Floskel. Damit steht Spruch gegen Spruch, und die Frage, woran man eine Wirkung erkennen würde, ist weiterhin offen."},{"option":2,"text":"Finanzielle Interessen können die Glaubwürdigkeit tatsächlich beeinflussen, die Frage kann also berechtigt sein. Ob die Methode wirkt, entscheidet sich dadurch aber nicht, und das Gespräch rückt von der Sache weg zur Person."},{"option":3,"text":"Die Frage nach eigenen Erfahrungen klingt zugewandt und lässt die Person zu Wort kommen. Sie liefert aber Einzelberichte statt Belege, und die Phrase „Vertraue dem Prozess“ bleibt unhinterfragt stehen."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism. Kap. 22, Abschnitt „Loading the Language“ (Nachdruck UNC Press 1989)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5cd2cff1255de4e9"}},{"id":"qx-d2-007","clusterId":"D","werkstueckRef":"D.3.4","stufe":3,"question":"Beim Familienessen spricht eine Studentin über strukturelle Ursachen von Armut. Ihr Vater winkt ab: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“ Worin liegt das eigentliche Problem seiner Reaktion?","options":["Er benutzt das Sprichwort als abschließende Antwort, ohne auf ihre Argumente einzugehen, und beendet damit das Gespräch, statt es zu prüfen.","Er greift die Studentin persönlich an, statt auf ihre Argumente einzugehen, und stellt sie dadurch als weltfremd und unerfahren hin.","Er beruft sich auf seine Stellung als Vater und ersetzt damit Gründe durch Autorität, sodass die Studentin nicht widersprechen kann.","Er gibt ihre Position verzerrt wieder, als behaupte sie, niemand könne etwas für sein Schicksal, und widerlegt dann nur diese Übertreibung."],"correctIndex":0,"explanation":"Ein Sprichwort zur Illustration ist völlig normal, denn solche Redewendungen sind nützliche Abkürzungen und „kultureller Klebstoff“. Zum Problem wird es, wenn es die Funktion eines Schlussstrichs bekommt: Die Studentin hat strukturelle Ursachen genannt, und der Vater geht auf keine davon ein, sondern erklärt die Debatte mit einer Phrase für beendet. Dabei muss die Phrase weder logisch noch wahr sein, um so zu wirken, denn ihre Kraft liegt in der scheinbaren Endgültigkeit und sozialen Akzeptanz. Entscheidend ist also nicht der Inhalt des Spruchs, sondern was er im Gespräch tut: Er ersetzt die Prüfung der Argumente. Wer ihn auspacken will, fragt, wie genau er auf dieses konkrete Problem passt und was er an den genannten Ursachen ändert. Einen persönlichen Angriff enthält seine Antwort nicht, er geht nur nicht auf die Sache ein. Auf seine Rolle als Vater beruft er sich nicht, seine Antwort stützt sich allein auf das Sprichwort. Und er gibt ihre Position nicht verzerrt wieder, er übergeht sie.","coreRule":"⚡ Nicht das Sprichwort ist das Problem, sondern seine Verwendung als Fragenkiller: Er ersetzt die Prüfung durch eine Phrase.","beleg":"Werkstück D.3.4 (Das Adaptive Talent; Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Das Sprichwort ist an sich harmlos, hier aber ein Schlussstrich: Der Vater geht auf keine der genannten strukturellen Ursachen ein und erklärt die Debatte mit einer Phrase für beendet, die allein durch ihre scheinbare Endgültigkeit wirkt.","prueffrage":"Wäre die Reaktion des Vaters weniger problematisch, wenn er denselben Gedanken in eigenen Worten statt als Sprichwort gesagt hätte?","rueckmeldung":[{"option":1,"text":"Abwinken kann sich abschätzig anfühlen, der Vater sagt über die Studentin selbst aber nichts. Er nennt sie weder weltfremd noch unerfahren. Das Problem liegt in dem, was fehlt: die Auseinandersetzung mit ihren Argumenten."},{"option":2,"text":"Väterliches Abwinken klingt nach „Ich weiß es besser, weil ich dein Vater bin“. Gesagt wird das aber nicht: Seine Antwort stützt sich allein auf das Sprichwort. Seine Rolle spielt in dem, was er sagt, keine Rolle."},{"option":3,"text":"Das Sprichwort wirkt wie ein Gegenpol zu ihrer Aussage, als wäre ihre These „niemand kann etwas dafür“. Der Vater gibt ihre Position aber gar nicht wieder, weder verzerrt noch sonst. Er übergeht sie, statt eine Übertreibung zu widerlegen."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism. Kap. 22, Abschnitt „Loading the Language“ (Nachdruck UNC Press 1989)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e9efd936a73efaf2"}},{"id":"qx-d2-008","clusterId":"D","werkstueckRef":"D.3.4","stufe":4,"question":"Wie reagierst du am besten auf diesen Gesprächsausgang?","options":["Du merkst, dass der Satz nichts widerlegt hat, und fragst, was er im konkreten Fall erklärt: etwa, wie ein Kind ohne weiterführende Schule vor Ort „schmieden“ soll.","Du merkst, dass der Satz zu allgemein ist, und hältst ihm ein ebenso allgemeines Gegenwort entgegen, etwa „Die Umstände formen den Menschen“, damit beide Seiten gleich stark dastehen.","Du merkst, dass Sprichwörter in Debatten nicht als Argument taugen, und erklärst die Aussage des Vaters für unzulässig, statt zu fragen, was sie für die genannten Ursachen bedeutet.","Du merkst, dass die Tochter ihre Aussagen zu Bildungschancen und Herkunft nicht belegt hat, und bittest sie, zuerst ihre Quellen zu nennen, bevor der Vater inhaltlich antworten muss."],"correctIndex":0,"explanation":"Der Satz wirkt endgültig, widerlegt aber nichts: Er ersetzt die Auseinandersetzung mit den genannten Faktoren durch eine allgemeine Formel. Solche Phrasen beenden das Nachdenken, statt es voranzubringen. Sinnvoll ist deshalb, die Formel auf den konkreten Fall anzuwenden und zu prüfen, was sie dort tatsächlich erklärt. So wird die Diskussion wieder auf die Sachebene gezwungen. Ein ebenso allgemeines Gegenwort ersetzt die Phrase nur durch eine zweite, ohne etwas zu prüfen. Das Sprichwort pauschal für unzulässig zu erklären, ersetzt die Phrase nur durch einen anderen Gesprächsabbruch. Von der Tochter zuerst Quellen zu verlangen, verschiebt die Beweislast, obwohl der Vater selbst nichts belegt hat.","coreRule":"⚡ Eine Phrase, die eine komplexe Frage beendet statt beantwortet, prüfst du, indem du sie auf den konkreten Fall anwendest.","beleg":"Werkstück D.3.4 (Kontext & Tiefe); Fn. gl-d-lifton (Lifton 1961/1989, Kap. 22, „Loading the Language“, S. 429)","status":"entwurf","scenario":"Beim Abendessen erzählt eine Studentin ihren Eltern, was sie im Seminar über die Ursachen von Armut gelernt hat: Bildungschancen, familiäre Herkunft, regionale Unterschiede. Ihr Vater winkt ab: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“ Das Gespräch verstummt.","quote":"","quoteLabel":"","kurz":"Der Satz wirkt endgültig, erklärt aber nichts über die genannten Faktoren. Der Fehler liegt darin, ihn als Antwort zu nehmen. Wer fragt, was er an einem konkreten Fall erklärt, holt das Gespräch auf die Sachebene zurück.","prueffrage":"Woran könntest du erkennen, ob das Schweigen am Tisch Zustimmung bedeutet oder nur ein abgebrochenes Gespräch?","rueckmeldung":[{"option":1,"text":"Dass der Satz sehr allgemein ist, stimmt. Ein ebenso allgemeines Gegenwort ersetzt die Phrase aber nur durch eine zweite, und am konkreten Fall wird weiterhin nichts geprüft."},{"option":2,"text":"Dass ein Sprichwort allein nichts belegt, ist richtig. Die Aussage für unzulässig zu erklären, beendet das Gespräch aber ein zweites Mal, statt zu klären, was sie für die genannten Ursachen heißen soll."},{"option":3,"text":"Quellen zu nennen ist grundsätzlich sinnvoll. Hier verlagert die Bitte aber die Beweislast auf die Tochter, obwohl der Vater selbst nichts belegt hat und die Phrase einfach im Raum stehen bliebe."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism. Kap. 22, Abschnitt „Loading the Language“ (Nachdruck UNC Press 1989)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d63f4da85f0e790c"}},{"id":"qx-d2-009","clusterId":"D","werkstueckRef":"D.3.5","stufe":1,"question":"Wie beurteilst du deine Antwort?","scenario":"Du sagst: „Kein echter Fan unseres Vereins pöbelt im Stadion.“ Dein Freund zeigt dir einen Mann im Vereinstrikot, der Gästefans beschimpft hat. Du antwortest: „Dann ist das eben kein echter Fan.“ Dein Freund fragt: „Woran erkenne ich denn einen echten Fan?“ Du sagst: „Na, daran, dass er nicht pöbelt.“","options":["Du rettest deine Aussage, indem du „echter Fan“ so umdefinierst, dass der pöbelnde Mann im Trikot nicht mehr zählt und die Aussage nichts mehr behauptet.","Du rettest deine Aussage, indem du vom Mann im Trikot ablenkst und auf provozierende Gästefans verweist, statt seinen Fall zu prüfen (Whataboutism).","Du rettest deine Aussage, indem du deinem Freund unterstellst, er halte jeden Fan des Vereins für einen Pöbler, und nur das widerlegst (Strohmann-Argument).","Du rettest deine Aussage, indem du dich darauf berufst, dass der Verein Pöbler selbst nicht als Fans zählt, statt den Mann im Trikot zu prüfen (Autoritätsargument)."],"correctIndex":0,"explanation":"Ursprünglich war deine Aussage überprüfbar: Man hätte einen pöbelnden Fan finden können, um sie zu widerlegen. Mit dem eingeschobenen „echt“ ist sie es nicht mehr. Ein „echter Fan“ ist jetzt per Definition einer, der nicht pöbelt, und die Aussage lautet nur noch: „Wer nicht pöbelt, pöbelt nicht.“ Das stimmt immer und sagt nichts über die Welt. Statt die Behauptung am Gegenbeispiel zu prüfen und womöglich einzuschränken („Die meisten Fans pöbeln nicht“), hast du das Gegenbeispiel aus der Kategorie ausgeschlossen. Das ist die nachträgliche Immunisierung, die als „Kein wahrer Schotte“-Fehlschluss bekannt ist. Der Verweis auf provozierende Gästefans wäre ein bekannter Kniff, du bleibst aber beim Mann im Trikot und änderst nur die Definition. Deinem Freund unterstellst du nichts, er fragt nur nach deinem Kriterium. Und auf den Verein als Zeugen berufst du dich nirgends.","coreRule":"⚡ Wenn ein Gegenbeispiel auftaucht und du die Definition änderst, statt die Behauptung zu prüfen, hast du sie unwiderlegbar und damit inhaltsleer gemacht.","beleg":"Werkstück D.3.5 (Kernidee; Red Flags)","status":"entwurf","kurz":"Mit „echt“ legst du fest, dass nur Nicht-Pöbler Fans sind, und aus der Aussage wird „Wer nicht pöbelt, pöbelt nicht“. Das stimmt immer und sagt nichts mehr, statt das Gegenbeispiel zu prüfen und die Aussage vielleicht einzuschränken.","prueffrage":"Welche Beobachtung im Stadion würde deine Aussage noch widerlegen können?","rueckmeldung":[{"option":1,"text":"Ablenken wäre ein echter Kniff, passiert hier aber nicht: Die Gästefans kommen nur als Beschimpfte vor, und du bleibst beim Mann im Trikot. Das Problem liegt darin, dass du ihn per Definition aus der Gruppe der Fans streichst."},{"option":2,"text":"Eine Unterstellung wäre ein bekannter Kniff, doch dein Freund unterstellt nichts: Er zeigt einen Fall und fragt dann nur nach deinem Kriterium. Du weichst nicht einer übertriebenen Position aus, sondern änderst die Bedeutung von „Fan“."},{"option":3,"text":"Sich auf den Verein als Zeugen zu berufen, ist ein bekannter Kniff, aber hier nennst du keine Instanz. Du legst selbst fest, wer als „echter Fan“ zählt, und genau diese Festlegung macht die Aussage unwiderlegbar."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flew, A. (1975): Thinking About Thinking. London: Fontana","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8f1b9bc0c29f06c8"}},{"id":"qx-d2-010","clusterId":"D","werkstueckRef":"D.3.5","stufe":2,"question":"Marta behauptet: „Alle Menschen, die sich ernsthaft für Gesundheit interessieren, ernähren sich bewusst.“ Als Tom einen bekannten Gesundheitsberater nennt, der täglich Fast Food isst, antwortet sie: „Dann interessiert er sich eben nicht wirklich für Gesundheit.“ Warum ist Martas Behauptung nach dieser Antwort kaum noch etwas wert?","options":["Mit dem Wort „wirklich“ wird die Tatsachenbehauptung zur bloßen Meinung, die man nicht mehr prüfen muss, solange sie niemanden verletzt oder herabsetzt.","Wer „wirklich“ an Gesundheit interessiert ist, erkennt man jetzt nur noch an der bewussten Ernährung; im Kern heißt die Aussage: „Wer sich bewusst ernährt, ernährt sich bewusst.“","Ein einzelnes Gegenbeispiel kann eine Aussage über alle Mitglieder einer Gruppe grundsätzlich nicht widerlegen, mit oder ohne „wirklich“.","Nach der Verschärfung bleibt die Aussage prüfbar, gilt aber nur noch für eine kleine Gruppe von Menschen und ist deshalb unbedeutend."],"correctIndex":1,"explanation":"Vorher war die Behauptung prüfbar: Ein Gesundheitsinteressierter mit schlechter Ernährung hätte sie widerlegt. Genau so jemand wurde genannt. Marta rettet ihre Aussage, indem sie das Gegenbeispiel aus der Kategorie wirft. Das Kriterium für „wirklich interessiert“ ist nun genau das, was behauptet wird, und die Aussage lautet im Kern: „Wer sich bewusst ernährt, ernährt sich bewusst.“ Das ist immer wahr und sagt nichts mehr über die Welt. Ein Gegenbeispiel kann eine Allaussage durchaus widerlegen. Gerade deshalb wird es ausgeschlossen.","coreRule":"⚡ Prüfe, ob sich das Kriterium für „wirklich“ unabhängig von der Behauptung bestimmen lässt; sonst ist die Behauptung leer.","beleg":"Werkstück D.3.5 (Kontext & Tiefe, „Der Mechanismus“)","status":"entwurf","scenario":"","kurz":"Marta macht „bewusste Ernährung“ zum Kriterium für „wirkliches Interesse“, also gerade zu dem, was sie behauptet. Der Satz kann dann nie mehr falsch sein und sagt nichts mehr über die Welt; das Gegenbeispiel hätte ihn vorher durchaus widerlegt.","prueffrage":"Welches Ergebnis hätte Martas Aussage vorher widerlegt, und gibt es dieses Ergebnis nach ihrer Antwort noch?","rueckmeldung":[{"option":0,"text":"Zur bloßen Meinung wird die Aussage durch „wirklich“ nicht, und ob sie jemanden verletzt, spielt für ihre Prüfbarkeit keine Rolle. Sie wird zu einem Satz, der per Definition immer stimmt und deshalb nichts mehr über die Welt sagt."},{"option":2,"text":"Ein einzelnes Gegenbeispiel kann eine Aussage über alle sehr wohl widerlegen. Hier greift es nur deshalb nicht mehr, weil Marta es mit „nicht wirklich“ aus der Gruppe herausdefiniert."},{"option":3,"text":"Dass die Gruppe schrumpft, stimmt. Prüfbar bleibt die Aussage danach aber nicht: Wer sich nicht bewusst ernährt, zählt nun per Definition nicht dazu. Das macht sie wertlos, nicht ihre geringe Reichweite."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"faa2bec355050156"}},{"id":"qx-d2-011","clusterId":"D","werkstueckRef":"D.3.5","stufe":3,"question":"Wie beurteilst du Lenas Satz zur Nichte und ihre Antwort an den Bruder?","options":["Der Satz zur Nichte setzt einen Maßstab, den Jonas’ Lüge nicht widerlegen kann; die Antwort an den Bruder rettet ihre Aussage über ihre Freunde, indem sie „Freund“ erst nach der Lüge enger fasst.","Beide Sätze sind gleich fragwürdig, weil Lena jedes Mal das Wort „echt“ benutzt; schon dieses Wort zeigt, dass sie Gegenbeispiele wie Jonas von vornherein aus ihrem Freundeskreis ausschließen will.","Beide Sätze sind unbedenklich, weil Lena selbst festlegen darf, wen sie Freund nennt; Jonas nach seiner Lüge herauszunehmen, ist dieselbe erlaubte Festlegung wie ihr Maßstab gegenüber der Nichte.","Der Satz zur Nichte ist der Fehlschluss, weil er ein Ideal als Beschreibung echter Freunde ausgibt; die Antwort an den Bruder ist dagegen sauber, weil sie nur auf Jonas’ tatsächliche Lüge reagiert."],"correctIndex":0,"explanation":"Lenas Satz zur Nichte ist eine Norm: Er behauptet nichts über die Welt, sondern legt fest, was man von Freunden erwarten darf. Ein Gegenbeispiel wie Jonas kann ihn nicht widerlegen, und er muss es auch nicht. „Alle meine Freunde sind ehrlich zu mir“ dagegen ist eine Tatsachenbehauptung, und Jonas’ Lüge widerlegt sie. Statt die Behauptung zu prüfen, verengt Lena den Begriff „Freund“ nachträglich so, dass Jonas herausfällt; übrig bleibt „Alle ehrlichen Freunde sind ehrlich“, eine Aussage, die nichts mehr behauptet und nicht mehr falsch sein kann. Verräterisch ist der Wechsel von „Stimmt das?“ zu „Wer zählt überhaupt dazu?“. Dass das Wort „echt“ in beiden Sätzen vorkommt, macht noch keinen Fehlschluss, entscheidend ist, wozu es dient. Eine Festlegung vorab ist erlaubt, eine Festlegung erst nach dem Gegenbeispiel, um eine Tatsachenbehauptung zu retten, ist es nicht. Und der Satz zur Nichte beschreibt keine Tatsache, er setzt einen Maßstab; der Fehler liegt in der Antwort an den Bruder.","coreRule":"⚡ Normen setzen ist erlaubt, Tatsachen mit einer nachträglichen Definition retten nicht.","beleg":"Werkstück D.3.5 (Das Adaptive Talent; Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Lena sagt ihrer zwölfjährigen Nichte, die von einer Freundin enttäuscht wurde: „Ein echter Freund würde dich nicht belügen.“ Eine Woche später erzählt Lena ihrem Bruder: „Alle meine Freunde sind ehrlich zu mir.“ Der Bruder erinnert sie daran, dass Jonas sie neulich über das geliehene Fahrrad angelogen hat. Lena antwortet: „Dann war Jonas eben kein echter Freund.“","kurz":"Der Satz zur Nichte setzt einen Maßstab, den ein Gegenbeispiel nicht trifft. Die Aussage über ihre Freunde ist eine Tatsachenbehauptung: Wer „Freund“ erst nach Jonas’ Lüge enger fasst, prüft sie nicht mehr, sondern rettet sie.","prueffrage":"Was hätte sich an Lenas Aussage über ihre Freunde geändert, wenn sie vor dem Hinweis des Bruders gesagt hätte, wen sie zu ihnen zählt?","rueckmeldung":[{"option":1,"text":"Das Wort „echt“ steht tatsächlich in beiden Sätzen, ein Fehlschluss entsteht daraus aber nicht. Es kommt darauf an, wozu es dient: Beim Satz zur Nichte formuliert es einen Maßstab, erst in der Antwort an den Bruder schließt es ein Gegenbeispiel aus."},{"option":2,"text":"Lena darf vorab festlegen, was sie von Freunden erwartet; das stimmt. Jonas aber erst nach seiner Lüge aus dem Begriff zu nehmen, um die Behauptung über ihre Freunde zu retten, ist etwas anderes als ein Maßstab vorab."},{"option":3,"text":"Die Bewertung ist vertauscht. Der Satz zur Nichte behauptet nichts über die Welt, er sagt, was man von Freunden erwarten darf, und wird durch Gegenbeispiele nicht berührt. Die Antwort an den Bruder reagiert nicht nur auf die Lüge, sie verändert dafür den Begriff „Freund“."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2b827be65b7a1522"}},{"id":"qx-d2-012","clusterId":"D","werkstueckRef":"D.3.5","stufe":4,"question":"Welche Rückfrage prüft die Behauptung des Coaches am besten?","scenario":"Ein Diätcoach sagt: „Wer sich wirklich an den Plan hält, nimmt ab. Wer nicht abnimmt, hat sich eben nicht wirklich daran gehalten.“","options":["Wer hat den Plan entwickelt, und verdient der Coach daran, wenn Menschen ihn kaufen?","Ist Abnehmen überhaupt das richtige Ziel, oder kommt es für die Gesundheit auf anderes an?","Welche Ausbildung hat der Coach, und wie lange arbeitet er schon in diesem Bereich?","Woran erkennt man vorab, wer sich richtig an den Plan gehalten hat, unabhängig vom Abnehmen?"],"correctIndex":3,"explanation":"Der Coach verschärft die Bedingung nachträglich: „Sich wirklich an den Plan halten“ heißt in seinem Satz faktisch „hat abgenommen“. Dadurch wird die Behauptung zur Tautologie („Wer abnimmt, nimmt ab“) und kann nie mehr widerlegt werden, denn jedes Scheitern wird einfach dem Anwender zugeschrieben. Die beste Prüfung verlangt ein Kriterium für „wirklich gehalten“, das unabhängig vom Ergebnis feststellbar ist, etwa Ernährungstagebuch, Wiegen der Portionen oder Kontrolle durch Dritte. Gibt es ein solches Kriterium nicht, sagt die Behauptung nichts über den Plan aus. Ob der Coach am Verkauf verdient oder welche Ausbildung er hat, kann für das Vertrauen eine Rolle spielen, sagt aber nichts darüber, ob seine Behauptung überhaupt widerlegbar ist. Ob Abnehmen das richtige Ziel ist, ist eine andere Frage als die nach der Behauptung des Coaches.","coreRule":"⚡ Verlange ein Kriterium für „echt“ oder „wirklich“, das nicht schon das Ergebnis voraussetzt.","beleg":"Werkstück D.3.5 (Anwendung & Relevanz, „Pseudowissenschaft & Kulte“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Der Coach macht „sich wirklich halten“ nachträglich zu „hat abgenommen“, damit kann ihm nichts widersprechen. Prüfbar wird die Aussage erst, wenn sich das Einhalten unabhängig vom Ergebnis feststellen lässt, etwa per Tagebuch.","prueffrage":"Welches Ergebnis eines Teilnehmers könnte der Coach überhaupt als Fehlschlag seines Plans anerkennen?","rueckmeldung":[{"option":0,"text":"Ein Verdienst am Verkauf kann Misstrauen wecken und ist durchaus bedenkenswert. Er verrät aber nicht, ob die Behauptung überhaupt widerlegbar ist; selbst ein Coach ohne Eigeninteresse könnte diesen Satz sagen."},{"option":1,"text":"Ob Abnehmen das richtige Ziel ist, ist eine eigene, berechtigte Frage. Sie betrifft aber die Wahl des Ziels, nicht die Aussage des Coaches, die sich gegen jedes Gegenbeispiel absichert."},{"option":2,"text":"Ausbildung und Erfahrung können das Vertrauen in einen Coach beeinflussen. Sie sagen aber nicht, ob seine Behauptung widerlegbar ist, denn auch ein erfahrener Coach kann jedes Scheitern den Anwendern zuschreiben."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"31a84875bde332af"}},{"id":"qx-d2-013","clusterId":"D","werkstueckRef":"D.3.6","stufe":1,"question":"Was ist an dieser Begründung das Problem?","scenario":"„Wie funktioniert die Wünschelrute?“ – „Sie reagiert auf Erdstrahlen.“ – „Was sind Erdstrahlen?“ – „Das, worauf die Wünschelrute reagiert.“","options":["Jede Seite stützt nur die andere; für keine von beiden gibt es einen unabhängigen Beleg.","Die Wünschelrute ist bisher nur durch Erfahrungsberichte gestützt, nicht durch Messungen; deshalb bleibt sie eine bloße Anekdote.","Der Begriff „Erdstrahlen“ ist zu unscharf definiert; mit einer genaueren Definition wäre die Begründung in Ordnung.","Der Sprecher beruft sich auf eine unsichtbare Kraft; unsichtbare Dinge dürfen nie Teil einer Begründung sein."],"correctIndex":0,"explanation":"Die Wirkung der Rute wird mit Erdstrahlen erklärt, und Erdstrahlen werden nur darüber bestimmt, dass die Rute auf sie reagiert. Beide Behauptungen stützen sich gegenseitig, und es fehlt der Anker in der überprüfbaren Realität: ein Beleg für eines von beiden, der nichts mit dem anderen zu tun hat. Das ist ein Zirkelschluss (petitio principii): Die Begründung setzt voraus, was sie begründen soll. Auch eine genauere Definition würde den Kreis nicht öffnen, solange sie sich wieder nur auf die Rute beruft. Und unsichtbare Dinge sind nicht grundsätzlich verboten, denn Elektronen sind auch unsichtbar. Entscheidend ist, ob es unabhängige Belege gibt, etwa Messungen, die nicht von der Rute abhängen.","coreRule":"⚡ Frag nach einem Beleg für eine der beiden Seiten, der nichts mit der anderen zu tun hat.","beleg":"Werkstück D.3.6 (Anwendung & Relevanz, „Pseudowissenschaft“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Die Rute soll durch Erdstrahlen erklärt werden, die Erdstrahlen aber nur dadurch, dass die Rute auf sie reagiert. So stützen sich beide gegenseitig, und es fehlt ein unabhängiger Beleg. Die Begründung setzt voraus, was sie zeigen soll.","prueffrage":"Was erfährst du über Erdstrahlen, wenn du die zweite Antwort in die erste einsetzt?","rueckmeldung":[{"option":1,"text":"Ob es für die Wünschelrute Messungen gibt, ist in diesem Wortwechsel gar nicht die Frage. Das Problem zeigt sich schon in ihm selbst: Rute und Erdstrahlen werden nur durcheinander erklärt, die Begründung dreht sich im Kreis."},{"option":2,"text":"Der Begriff ist tatsächlich leer, doch Schärfe allein hilft nicht: Eine Definition, die sich wieder nur auf die Rute beruft, schließt den Kreis nur enger. Öffnen könnten ihn erst Messungen, die von der Rute unabhängig sind."},{"option":3,"text":"Unsichtbares klingt verdächtig, ist aber nicht grundsätzlich ausgeschlossen: Auch Elektronen sieht man nicht, und sie sind belegt. Es kommt nicht auf die Sichtbarkeit an, sondern darauf, ob unabhängige Belege vorliegen."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitte Begging the Question, Circular Reasoning). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (Fassung vom 30.08.2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ca53c3c26d20b8cd"}},{"id":"qx-d2-014","clusterId":"D","werkstueckRef":"D.3.6","stufe":2,"question":"Eine Anhängerin sagt: „Unsere Gruppe liegt richtig, weil nur wahre Mitglieder die Wahrheit erkennen, und wer die Wahrheit erkennt, ist ein wahres Mitglied.“ Ein Kritiker wendet ein: „Aber Mitglied X hat Gelder veruntreut.“ Sie antwortet: „Dann war er nie ein wahres Mitglied.“ Welche Analyse beschreibt beide Aussagen der Anhängerin am treffendsten?","options":["Die erste Aussage setzt voraus, was sie beweisen soll, und sichert so die Grundbehauptung ab; die zweite weist einen Einwand ab, indem sie den Begriff „wahres Mitglied“ nachträglich enger zieht.","Die erste Aussage weist einen Einwand ab, indem sie den Begriff „wahres Mitglied“ nachträglich enger zieht; die zweite setzt voraus, was sie beweisen soll, und sichert so die Grundbehauptung ab.","Beide Aussagen haben denselben Fehler, nur in zwei Formulierungen: Die zweite Aussage wiederholt lediglich die erste in anderen Worten.","Beide Aussagen sind keine Fehlschlüsse, weil jede Gruppe das Recht hat, ihre Begriffe selbst festzulegen und gegen Einzelfälle zu verteidigen."],"correctIndex":0,"explanation":"Die erste Aussage ist ein Zirkelschluss: „Wahr ist, was wahre Mitglieder erkennen“ und „wahres Mitglied ist, wer das Wahre erkennt“ stützen sich gegenseitig, ohne dass irgendein Beleg von außen hinzukommt. Die zweite Aussage hat eine andere Funktion: Sie reagiert auf einen konkreten Einwand und rettet die Behauptung, indem der Begriff „wahres Mitglied“ im Nachhinein so definiert wird, dass der Gegenfall nicht mehr zählt (der „Kein wahrer Schotte“-Trick). Die zweite Aussage wiederholt die erste also nicht in anderen Worten, sondern antwortet auf einen Angriff von außen. Es sind zwei verschiedene Fehler: Der eine baut die Struktur des Dogmas, der andere ist die Verteidigungstaktik dagegen. Dass eine Gruppe ihre Begriffe frei setzen darf, ändert nichts daran, dass solche Setzungen nichts beweisen.","coreRule":"⚡ Wer den Beweis in die Behauptung einbaut, baut einen Kreis (Zirkelschluss); wer den Begriff nach dem Einwand enger zieht, verteidigt ihn (Kein wahrer Schotte).","beleg":"Werkstück D.3.6 (Kontext & Tiefe, „Abgrenzung zum Kein wahrer Schotte“; Verbindungen)","status":"entwurf","scenario":"","kurz":"Die erste Aussage stützt sich nur selbst: Die Wahrheit erkennen nur wahre Mitglieder, und wahres Mitglied ist, wer die Wahrheit erkennt. Die zweite zieht den Begriff erst nach dem Einwand enger. Das sind zwei Fehler: ein Zirkel und eine nachträgliche Rettung.","prueffrage":"Was müsste die Anhängerin vorlegen, damit ein Außenstehender ihre Grundbehauptung prüfen kann?","rueckmeldung":[{"option":1,"text":"Die Reihenfolge im Gespräch spricht dagegen: Der Einwand kommt erst, nachdem der erste Satz gefallen ist, also kann dieser ihn gar nicht abwehren. Erst die Antwort „nie ein wahres Mitglied“ zieht den Begriff nachträglich enger."},{"option":2,"text":"Beide Sätze schützen die Gruppe, das stimmt. Die zweite Aussage wiederholt die erste aber nicht, sondern antwortet auf einen konkreten Angriff von außen. Es sind zwei verschiedene Fehler: der eine baut das Dogma, der andere verteidigt es."},{"option":3,"text":"Begriffe zu setzen steht jeder Gruppe frei, aber solche Setzungen beweisen nichts. Hier stützt der erste Satz sich nur selbst, und im zweiten wird die Definition erst nach dem Einwand so zugeschnitten, dass der Gegenfall nicht mehr zählt."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitte Circular Reasoning, No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2b7917e70b419d2d"}},{"id":"qx-d2-015","clusterId":"D","werkstueckRef":"D.3.6","stufe":3,"question":"Ein Kollege argumentiert: „Meine Methode ist zuverlässig. Warum? Weil sie funktioniert – und dass sie funktioniert, sieht man daran, dass sie zuverlässig ist.“ Du entgegnest, das sei ein Zirkelschluss. Er kontert: „Aber logisch ist das einwandfrei: Wenn die Prämisse stimmt, stimmt auch die Schlussfolgerung.“ Warum ändert dieser Einwand nichts daran, dass das Argument nichts beweist?","options":["Weil er die Beweislast umkehrt: Nicht er muss die Zuverlässigkeit belegen, sondern du ihr Gegenteil.","Weil er von einem einzelnen Erfolg auf alle künftigen Fälle schließt, ohne zu zeigen, dass der Erfolg kein Zufall war.","Weil der Schluss gültig ist, die Prämisse aber nicht besser gestützt ist als die Konklusion, die sie stützen soll.","Weil er mit der Beliebtheit der Methode argumentiert, obwohl Beliebtheit allein nichts über ihre Zuverlässigkeit sagt."],"correctIndex":2,"explanation":"Gültigkeit und Beweiskraft sind zwei verschiedene Dinge. „P, also P“ ist formal gültig: Wenn die Prämisse stimmt, stimmt auch die Konklusion. Aber die Prämisse taugt nur so viel wie die Konklusion, die sie stützen soll – hier sagt sie schlicht dasselbe in anderen Worten. Ein solches Argument predigt nur zu denen, die bereits glauben. Der Einwand des Kollegen trifft also ins Leere: Die Form ist in Ordnung, aber es fehlt ein unabhängiger, externer Anker, der die Prämisse trägt.","coreRule":"⚡ Gültig ist nicht beweisend: Ein Schluss, der sein Ergebnis voraussetzt, überzeugt nur Überzeugte.","beleg":"Werkstück D.3.6 (Kontext & Tiefe, „Logische Form“ und „Mechanik des Beweisgrund-Erschleichens“)","status":"entwurf","scenario":"","kurz":"Der Schluss „P, also P“ ist zwar gültig, aber die Prämisse sagt nur dasselbe wie die Konklusion und stützt sie daher nicht. Gültige Form ist nicht Beweiskraft: Es fehlt ein unabhängiger Beleg, der die Zuverlässigkeit trägt.","prueffrage":"Was müsste der Kollege zusätzlich vorlegen, damit jemand, der an der Methode zweifelt, überzeugt wäre?","rueckmeldung":[{"option":0,"text":"Wer etwas behauptet, muss es auch belegen, das ist ein vernünftiger Maßstab. Hier aber verlangt der Kollege gar nichts von dir; sein Fehler liegt darin, dass die Begründung die Behauptung nur wiederholt."},{"option":1,"text":"Ein Einzelfall als Grundlage für ein allgemeines Urteil wäre tatsächlich ein typischer Fehler. Der Kollege nennt aber keinen einzelnen Erfolg, von dem er verallgemeinert; das Problem steckt in der Kreisförmigkeit seiner Begründung."},{"option":3,"text":"Beliebtheit allein sagt tatsächlich nichts über Zuverlässigkeit. Der Kollege beruft sich aber nicht darauf, wie verbreitet seine Methode ist, sondern begründet sie mit sich selbst."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (Fassung vom 30.08.2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"16–17","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"85fa6d737bc7e1a4"}},{"id":"qx-d2-016","clusterId":"D","werkstueckRef":"D.3.6","stufe":4,"question":"Beide Argumente sind gleich gebaut. Worin liegt trotzdem der entscheidende Unterschied?","scenario":"Zwei Argumente im Vergleich:\\n\\n(1) „Elektronen gibt es, denn in der Nebelkammer sehen wir Spuren, und solche Spuren sind die Signatur von Elektronen.“\\n\\n(2) „Gott existiert, denn die Bibel sagt es, und die Bibel ist Gottes Wort.“\\n\\nBeide Male wird die Behauptung teilweise schon in der Begründung vorausgesetzt.","options":["Beim Elektronen-Argument sind andere Deutungen der Spuren sehr unwahrscheinlich, beim Bibel-Argument gibt es viele plausible andere Deutungen.","Beim Elektronen-Argument wird die Behauptung nur teilweise vorausgesetzt, beim Bibel-Argument vollständig, deshalb ist nur das zweite zirkulär.","Beim Elektronen-Argument liefern Messgeräte die Belege, beim Bibel-Argument ein Text, und Messdaten sind schon wegen ihrer Art stärker.","Beim Elektronen-Argument stimmen heute fast alle Fachleute zu, beim Bibel-Argument nicht, und diese Zustimmung allein macht das Argument stärker."],"correctIndex":0,"explanation":"Nicht jede stillschweigende Voraussetzung ist ein Fehlschluss. Auch in der Wissenschaft wird überall dort, wo Dinge nicht direkt beobachtbar sind, auf die beste Erklärung geschlossen, und dieser Schluss hat dieselbe Form wie das zweite Argument. Den Unterschied machen die Wahrscheinlichkeiten: Für die Bibel gibt es viele andere plausible Deutungen, als dass sie Gottes Wort ist; beim Elektronen-Schluss ist das nicht der Fall. Untersuchungen zur Stärke von Argumenten (Hahn und Oaksford, 2006, 2007) zeigen, dass dieselbe Argumentform je nach Inhalt unterschiedlich stark sein kann.","coreRule":"⚡ Gleiche Form heißt nicht gleiche Beweiskraft: Frag, wie plausibel die Alternativen zur vorgeschlagenen Erklärung sind.","beleg":"Werkstück D.3.6 (Der Kipppunkt); Fn. gl-d-hahn (Hahn/Oaksford 2006, S. 16–17)","status":"entwurf","kurz":"Beide Argumente schließen auf die beste Erklärung, und das ist an sich legitim. Entscheidend ist, wie viele andere plausible Deutungen es gibt: bei den Nebelkammer-Spuren kaum, bei der Bibel viele. Gleiche Form, unterschiedliche Stärke.","prueffrage":"Wenn Fachleute die Spuren in der Nebelkammer und den Bibeltext untersuchen: Wie einig sind sie sich jeweils über deren Herkunft?","rueckmeldung":[{"option":1,"text":"Dass die Begründung die Behauptung schon halb enthält, erscheint beim zweiten Argument stärker. Laut Szenario steckt sie aber in beiden Fällen teilweise darin, und eine solche Voraussetzung ist nicht von selbst ein Fehler."},{"option":2,"text":"Messdaten sind oft verlässlich, deshalb liegt die Antwort nahe. Die Art der Quelle entscheidet aber nicht über die Stärke: Es kommt darauf an, wie gut andere Deutungen der Belege ausgeschlossen werden können."},{"option":3,"text":"Breite Zustimmung kann ein Hinweis auf gute Belege sein. Sie ist aber eher Folge starker Belege als deren Grund und macht ein Argument nicht für sich genommen stärker."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"16–17","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hahn, U.; Oaksford, M. (2007): The Rationality of Informal Argumentation: A Bayesian Approach to Reasoning Fallacies. Psychological Review 114(3), 704–732","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bcdfc8b51404ee3f"}},{"id":"qx-d2-017","clusterId":"D","werkstueckRef":"D.3.7","stufe":1,"question":"Wie beurteilst du die beiden Wortmeldungen, und was sollte das Team daraus machen?","options":["Beide schließen nur von der Herkunft auf das Ergebnis; das Team sollte die Studie lesen und das Pharma-Geld höchstens als Anlass nehmen, Methode und Daten besonders genau zu prüfen.","Nur Frau Okafor schließt vorschnell, denn ein Universitätsname belegt kein Ergebnis; das Team sollte die Studie wegen des Pharma-Geldes vorerst beiseitelegen, bis eine unabhängige vorliegt.","Nur Herr Brandt schließt vorschnell, denn ein Geldgeber sagt nichts über ein Ergebnis; das Team sollte der Studie wegen der renommierten Universität vorerst vertrauen und sie aufnehmen.","Beide nennen einen sachlichen Umstand der Studie; das Team sollte abwägen, ob das Pharma-Geld oder der Ruf der Universität schwerer wiegt, und je nach Ergebnis aufnehmen oder verwerfen."],"correctIndex":0,"explanation":"Herr Brandt und Frau Okafor schließen allein von der Herkunft auf die Wahrheit, ohne Inhalt, Logik oder Evidenz anzusehen; gelesen hat die Studie ja noch niemand. Herr Brandt macht den genetischen Fehlschluss („schlechte Quelle, also falsch“), Frau Okafor den Appell an die Autorität („gute Quelle, also wahr“); beide Fehler sind spiegelbildlich gebaut. Eine schlechte Bilanz der Quelle darf Anlass sein, besonders kritisch zu prüfen, ein guter Ruf Anlass zu Vertrauen, die Prüfung der Belege ersetzen kann aber beides nicht. Ein sauberes Ergebnis bleibt sauber, auch wenn ein Konzern es bezahlt hat, und ein schwaches wird durch den Namen einer Universität nicht stärker. Jeweils nur einen der beiden zu rügen, klingt ausgewogen, übernimmt aber das Herkunftsurteil des anderen. Und Geldgeber gegen Universitätsruf abzuwägen, wirkt sachlich, bleibt aber ein Vergleich zweier Etiketten, in dem die Studie selbst nicht vorkommt.","coreRule":"⚡ Prüfe den Inhalt, nicht das Etikett der Herkunft, in beide Richtungen.","beleg":"Werkstück D.3.7 (Kernidee)","status":"entwurf","scenario":"Ein Team soll entscheiden, ob es eine neue Studie zu einem Schmerzmittel in seine Empfehlungen aufnimmt. Gelesen hat sie noch niemand. Herr Brandt sagt: „Die Studie ist von einem Pharmakonzern bezahlt, also ist ihr Ergebnis falsch.“ Frau Okafor sagt: „Die Studie stammt von einer renommierten Universität, also ist ihr Ergebnis richtig.“","kurz":"Beide urteilen über eine ungelesene Studie nur nach ihrer Herkunft. Geldgeber oder Ruf dürfen Anlass sein, genauer hinzusehen, ersetzen aber nicht die Prüfung von Methode und Daten; erst die entscheidet, was die Studie wert ist.","prueffrage":"Was an der Studie selbst, nicht an ihrer Herkunft, haben Herr Brandt und Frau Okafor bisher angesehen?","rueckmeldung":[{"option":1,"text":"Dass ein Universitätsname kein Ergebnis belegt, stimmt. Wer die Studie aber wegen des Geldgebers beiseitelegt, urteilt genauso nach Herkunft wie Herr Brandt, nur in die andere Richtung."},{"option":2,"text":"Dass ein Geldgeber allein nichts über ein Ergebnis sagt, stimmt. Dem Ruf der Universität zu vertrauen, ist aber derselbe Schluss von der Herkunft, nur mit umgekehrtem Vorzeichen; geprüft wäre damit nichts."},{"option":3,"text":"Geldgeber und Universität sind tatsächlich Umstände der Studie, und der Geldgeber darf zu genauerem Hinsehen anregen. Beide gegeneinander abzuwägen, vergleicht aber nur zwei Etiketten, während die Studie selbst gar nicht vorkommt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Einträge „Genetic Fallacy“, „Appeal to Authority“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2e151c3e2d46c133"}},{"id":"qx-d2-018","clusterId":"D","werkstueckRef":"D.3.7","stufe":2,"question":"Welche Rückfrage prüft diese Behauptung am besten?","scenario":"In einer Diskussion über ein Förderprogramm sagt jemand: „Die Grundidee dieses Programms stammt ursprünglich von einer Lobbygruppe. Deshalb ist sie falsch, egal ob die Daten dazu etwas anderes zeigen.“ Die Daten zu dem Programm hat er sich nicht angesehen.","options":["Wie belastbar sind die Daten zum Programm, wenn du sie unabhängig davon betrachtest, wer die Grundidee zuerst entwickelt hat?","Welche anderen Förderprogramme verfolgen dasselbe Ziel, und wie fällt ein Vergleich ihrer Kosten mit diesem Programm aus?","Welche Ziele verfolgt die Lobbygruppe sonst noch, und von wem wird sie bezahlt, wenn sie solche Ideen vorbringt?","Wie hat sich die Haltung der Öffentlichkeit zum Programm entwickelt, seit die Herkunft der Grundidee aus der Lobbygruppe bekannt ist?"],"correctIndex":0,"explanation":"Der Einwand verwirft eine Idee allein wegen ihres Ursprungs. Ob sie stimmt, hängt aber an Inhalt, Logik und Evidenz, nicht daran, wer sie zuerst hatte; deshalb lenkt die beste Rückfrage auf die Daten und trennt sie von der Herkunft. Der Ursprung darf ein Anlass sein, genauer hinzuschauen und nach unabhängiger Bestätigung zu suchen, als Urteil über die Wahrheit taugt er nicht. Ein einfacher Prüftest: Stell dir vor, dieselbe Information stünde anonym auf einem Zettel, und bewerte dann die Belege.","coreRule":"⚡ Ursprung einer Idee ist ein Anlass zum Prüfen, kein Urteil.","beleg":"Werkstück D.3.7 (Kontext & Tiefe, „Abgrenzung zum Ad Hominem“)","status":"entwurf","kurz":"Ob das Programm wirkt, zeigen Inhalt und Daten, nicht die Herkunft der Idee. Wer sie allein wegen ihres Ursprungs verwirft, urteilt über die Quelle statt über die Belege; die Herkunft kann höchstens Anlass sein, genauer hinzusehen.","prueffrage":"Worauf stützt der Sprecher sein Urteil „falsch“, und was hat er sich dafür selbst angesehen?","rueckmeldung":[{"option":1,"text":"Ein Kostenvergleich mit anderen Programmen ist bei einer Entscheidung durchaus sinnvoll. Er sagt aber nichts darüber, ob die Behauptung des Sprechers trägt, denn die Daten zu diesem Programm bleiben dabei ungeprüft."},{"option":2,"text":"Wer hinter einer Idee steht, kann ein guter Anlass sein, genauer hinzuschauen. Über Ziele und Geldgeber erfährst du aber nur mehr über die Herkunft, und über die Daten zum Programm sagt das nichts."},{"option":3,"text":"Die Haltung der Öffentlichkeit zeigt, wie das Programm gesehen wird, nicht, ob es wirkt. Außerdem knüpft diese Frage wieder an die Herkunft an und lässt die Belege aus."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Genetic Fallacy“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"caa562b40df68d59"}},{"id":"qx-d2-019","clusterId":"D","werkstueckRef":"D.3.7","stufe":3,"question":"Welche Reaktion ist hier vernünftig, ohne in einen Denkfehler zu kippen?","scenario":"Dir liegt eine Studie vor, die von einem Konzern finanziert wurde, dem du misstraust. Du weißt, dass solche Auftraggeber in der Vergangenheit Studien manipuliert haben. Ein Bekannter sagt: „Die Studie kannst du dir sparen, die ist von denen bezahlt.“","options":["Die Studie erst dann misstrauisch lesen, wenn sich in ihr selbst Widersprüche zeigen, denn ohne Widerspruch fehlt jeder Anlass.","Die Studie wie jede andere behandeln und die Vorgeschichte des Konzerns ausblenden, denn sie lässt keinen Schluss auf diese Studie zu.","Die Studie besonders genau prüfen und nach unabhängiger Bestätigung suchen, denn die schlechte Bilanz des Konzerns verlangt mehr Sorgfalt.","Die Studie ungelesen beiseitelegen, bis eine unabhängige Stelle sie bestätigt, denn bei diesem Geldgeber lohnt die Lektüre vorher nicht."],"correctIndex":2,"explanation":"Misstrauen gegenüber einer Quelle mit schlechter Bilanz ist berechtigt, solange es dazu führt, die Studie besonders kritisch zu prüfen und nach unabhängiger Bestätigung zu suchen. Zum Fehlschluss wird es, wenn die Herkunft allein als Beweis gegen den Inhalt gilt („von denen bezahlt, also falsch“, der genetische Fehlschluss). Eine Idee ist an Inhalt, Logik und Evidenz zu bewerten, nicht an ihrem Ursprung. Erst bei sichtbaren Widersprüchen misstrauisch zu werden übersieht, dass die Vorgeschichte hier schon Grund zur Sorgfalt gibt. Die Vorgeschichte einfach auszublenden verschenkt genau diesen Hinweis. Und die Studie ungelesen wegzulegen, bis jemand sie bestätigt, ist der Fehlschluss selbst: Die Herkunft ersetzt dann die Prüfung des Inhalts.","coreRule":"⚡ Schlechte Bilanz heißt: genauer prüfen, nicht: ungelesen verwerfen.","beleg":"Werkstück D.3.7 (Der Kipppunkt)","status":"entwurf","kurz":"Die schlechte Bilanz des Geldgebers ist ein Grund, genauer hinzusehen und unabhängige Bestätigung zu suchen. Zum Fehlschluss wird sie erst, wenn die Herkunft allein den Inhalt entscheiden soll („von denen bezahlt, also falsch“).","prueffrage":"Was weißt du über diese konkrete Studie bisher, außer wer sie bezahlt hat?","rueckmeldung":[{"option":0,"text":"Gelesen wird die Studie hier ohnehin, und ein Urteil allein nach der Herkunft wäre verfrüht. Warten, bis sich Widersprüche zeigen, übersieht aber, dass die Vorgeschichte schon jetzt Grund zur Sorgfalt gibt."},{"option":1,"text":"Die Herkunft allein belegt tatsächlich nicht, dass diese Studie falsch ist. Sie völlig auszublenden verschenkt aber einen berechtigten Hinweis: Er spricht nicht gegen den Inhalt, wohl aber für genaueres Prüfen."},{"option":3,"text":"Unabhängige Bestätigung zu suchen ist sinnvoll. Wer die Studie dafür ungelesen weglegt, lässt aber die Herkunft die Prüfung ersetzen. Genau das ist der Fehlschluss: Der Inhalt wird gar nicht erst angeschaut."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Einträge „Genetic Fallacy“, „Appeal to Authority“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"4124321b3fb9c77c"}},{"id":"qx-d2-020","clusterId":"D","werkstueckRef":"D.3.7","stufe":4,"question":"Welcher Schritt hilft dir am besten, die Bewertung des Punktes vom Absender zu trennen?","scenario":"Ein Gesetzesvorschlag der Partei, die du ablehnst, enthält einen Punkt, der dir eigentlich einleuchtet. Du merkst, dass du ihn vor allem wegen des Absenders ablehnen willst.","options":["Nachsehen, ob die Partei den Punkt früher selbst abgelehnt hat, und dein Urteil davon abhängig machen, wie konsequent sie bisher gehandelt hat.","Den Punkt mit dem Wahlprogramm der Partei vergleichen, um zu sehen, ob er zu ihrer Linie passt, und danach entscheiden, wie ernst er gemeint ist.","Eine Nacht darüber schlafen, bis sich dein Ärger über die Partei gelegt hat, und den Punkt danach noch einmal wie gewohnt lesen.","Dir den Punkt ohne Absender oder als Vorschlag einer Seite vorstellen, der du vertraust, und prüfen, ob sich dein Urteil über den Inhalt dann ändert."],"correctIndex":3,"explanation":"Deine Ablehnung gilt hier dem Absender, nicht dem Inhalt. Das ist ein genetischer Fehlschluss: Ob ein Vorschlag sinnvoll ist, hängt an Inhalt, Logik und Evidenz, nicht an seinem Ursprung. Der Gedankentest mit fehlendem oder vertauschtem Absender löst die Bewertung vom Ursprung und zeigt, ob du den Inhalt oder nur den Absender beurteilst. Zu prüfen, wie konsequent die Partei bisher war oder ob der Punkt zu ihrem Wahlprogramm passt, bleibt beim Absender und sagt nichts über den Inhalt. Und zu warten, bis sich der Ärger legt, ändert nichts daran, woran du den Punkt misst.","coreRule":"⚡ Stell dir die Information anonym vor: Hält der Inhalt dann stand?","beleg":"Werkstück D.3.7 (Anti-Denkmuster, Skript 1; Anwendung & Relevanz, „Politische Ideologie“)","status":"entwurf","kurz":"Ob ein Vorschlag taugt, hängt an Inhalt, Logik und Belegen, nicht an seiner Herkunft. Wer ihn gedanklich von seinem Absender löst, sieht, ob das Urteil dem Inhalt gilt oder nur dem Absender, und verhindert so einen genetischen Fehlschluss.","prueffrage":"Welche Gründe gegen den Punkt selbst fallen dir ein, die nichts mit der Partei zu tun haben?","rueckmeldung":[{"option":0,"text":"Wie konsequent die Partei früher handelte, sagt etwas über ihre Glaubwürdigkeit. Das ist eine andere Frage als die nach dem Punkt selbst, dessen Wert vom Vorschlagenden unabhängig bleibt."},{"option":1,"text":"Das Wahlprogramm zeigt, wie ernst der Vorschlag gemeint sein könnte. Es sagt aber nichts darüber, ob der Punkt sinnvoll ist, und führt dich wieder zum Absender statt zum Inhalt."},{"option":2,"text":"Mit weniger Ärger liest du vermutlich ruhiger. Gemessen wird der Punkt danach aber noch immer am selben Maßstab, und der Absender bleibt im Hintergrund präsent, wenn du ihn nicht bewusst ausblendest."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Genetic Fallacy“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"b3ef33860c7d0fde"}},{"id":"qx-d2-021","clusterId":"D","werkstueckRef":"D.3.8","stufe":1,"question":"Was ist an diesem Schluss logisch fehlerhaft?","scenario":"Auf einer Podiumsdiskussion verteidigt ein Erfinder sein Perpetuum mobile gegen die Kritik von Physikern: „Jede große Wahrheit wurde zuerst bekämpft. Meine Maschine wird bekämpft. Also steckt eine große Wahrheit darin.“","options":["Er kehrt eine Aussage um: Aus „Große Wahrheiten wurden zuerst bekämpft“ folgt nicht „Alles, was bekämpft wird, ist eine große Wahrheit“.","Er beruft sich auf eine Autorität, die für Fragen der Physik gar nicht zuständig ist, und ersetzt so den Beleg für sein Perpetuum mobile (falsche Autorität).","Er verschiebt die Beweislast, indem er von den Physikern verlangt zu zeigen, dass sein Perpetuum mobile nicht funktioniert (Beweislastumkehr).","Er argumentiert im Kreis, weil „In meiner Maschine steckt eine große Wahrheit“ in der ersten Aussage schon enthalten ist (Zirkelschluss)."],"correctIndex":0,"explanation":"Der Schluss hat die Form „Alle A sind B, dies ist B, also ist dies A“: Aus „Große Wahrheiten wurden bekämpft“ folgt nicht „Alles Bekämpfte ist eine große Wahrheit“. Carl Sagan nennt Fulton und die Brüder Wright als Verlachte, aber auch Bozo den Clown. Ablehnung trifft Genies und Irrtümer gleichermaßen und unterscheidet beide deshalb nicht. Eine Autorität beruft der Erfinder nicht an, einen Beleg ersetzt er also auch nicht auf diese Weise. Die Beweislast schiebt er den Physikern nicht zu, er fordert von ihnen nichts. Und ein Zirkel liegt nicht vor, weil die Schlussfolgerung in der ersten Aussage noch nicht steckt.","coreRule":"⚡ Dass manche Genies verlacht wurden, macht nicht jeden Verlachten zum Genie.","beleg":"Werkstück D.3.8 (Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Verlachte Ideen waren manchmal große Wahrheiten, aber eben auch bloße Irrtümer. Wer „große Wahrheiten wurden bekämpft“ zu „Bekämpftes ist eine große Wahrheit“ umkehrt, schließt unzulässig: Ablehnung trifft Genies und Irrtümer gleichermaßen und unterscheidet sie nicht.","prueffrage":"Wird nur Richtiges abgelehnt, oder gibt es auch abgelehnte Ideen, die sich später als Irrtum erwiesen?","rueckmeldung":[{"option":1,"text":"Der Erfinder zitiert niemanden und beruft sich auf keine Autorität. Er verweist nur darauf, dass er bekämpft wird. Dass ein Beleg für sein Perpetuum mobile fehlt, stimmt, aber die Lücke ist ein falscher Umkehrschluss, kein Rückgriff auf unzuständige Experten."},{"option":2,"text":"Eine Umkehr der Beweislast würde voraussetzen, dass er von den Physikern verlangt, das Gegenteil zu zeigen. Das tut er nicht: Er fordert nichts von ihnen, sondern schließt aus der Ablehnung auf die Wahrheit seiner Maschine."},{"option":3,"text":"Ein Zirkel läge vor, wenn die Schlussfolgerung schon in der ersten Aussage steckte. Dort steht aber nur, dass große Wahrheiten bekämpft wurden. Der Schluss auf die Maschine kommt erst durch die unzulässige Umkehrung hinzu."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Einträge „Affirming the Consequent“, „Undistributed Middle“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain, Kap. 5 „Night Walkers and Mystery Mongers“","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"99626f2eb431a890"}},{"id":"qx-d2-022","clusterId":"D","werkstueckRef":"D.3.8","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Aus „Manche echten Neuerer wurden zunächst abgelehnt“ folgt nicht „Wer abgelehnt wird, ist ein echter Neuerer“.","Aus „Alle Fachleute lehnen die Theorie ab“ folgt nicht „Die Fachleute liegen mit ihrer gemeinsamen Ablehnung richtig“.","Aus „Erst lachten die Gelehrten, später wurde Galilei bestätigt“ folgt nicht „Das Lachen hat die spätere Bestätigung bewirkt“.","Aus „Er legt keine eigenen Daten zu seiner Theorie vor“ folgt nicht „Seine Theorie über die Krankheit ist falsch“."],"correctIndex":0,"explanation":"Der Schluss kehrt eine wahre Aussage unzulässig um: Dass einige Genies zunächst abgelehnt wurden, heißt nicht, dass jeder Abgelehnte ein Genie ist. Abgelehnt werden auch unzählige Theorien, die sich als falsch erweisen, nur bleiben sie nicht in Erinnerung, weil niemand ihre Geschichten erzählt. Ablehnung trifft Genie und Irrtum gleichermaßen und trennt beide deshalb nicht, ganz gleich, aus wie vielen Fachrichtungen sie kommt. Entscheidend ist, ob die Theorie prüfbare Belege oder Vorhersagen liefert, so wie Galilei Beobachtungen hatte, die jeder mit einem Fernrohr nachprüfen konnte. Dass einmütige Ablehnung durch Fachleute noch nicht beweist, dass sie recht haben, stimmt zwar, ist aber nicht der Fehler des Redners. Er behauptet auch keine Ursache zwischen dem Lachen und Galileis Bestätigung. Und fehlende Daten machen eine Theorie nicht schon falsch, nur schließt der Redner gerade nicht auf Falschheit, sondern aus der Ablehnung auf Genialität.","coreRule":"⚡ Ablehnung allein beweist nichts: Zähle auch die Bozos, nicht nur die Galileis, und frage nach prüfbaren Belegen.","beleg":"Werkstück D.3.8 (Kontext & Tiefe, „Die Basisrate wird unterschlagen“; Das Adaptive Talent)","status":"entwurf","scenario":"Auf einer Veranstaltung stellt ein Redner seine neue Theorie über die Ursache einer Krankheit vor. Nach Belegen gefragt, legt er keine eigenen Daten vor und sagt: „Meine Theorie wird von allen Fachleuten abgelehnt. Das zeigt, dass ich ein Genie bin – über Galilei haben sie auch gelacht.“","quote":"","quoteLabel":"","kurz":"Dass einige echte Neuerer zunächst abgelehnt wurden, macht nicht jeden Abgelehnten zum Neuerer: Auch viele Irrtümer werden abgelehnt, nur erinnert sich niemand an sie. Ablehnung trennt Genie und Irrtum nicht.","prueffrage":"Wie viele abgelehnte Theorien kennst du, die sich später als falsch erwiesen haben, und wer erzählt ihre Geschichten?","rueckmeldung":[{"option":1,"text":"Dass einmütige Ablehnung durch Fachleute nicht beweist, dass sie recht haben, stimmt. Der Redner behauptet das aber gar nicht, sondern folgert aus der Ablehnung seine eigene Genialität."},{"option":2,"text":"Das Lachen hat Galileis spätere Bestätigung tatsächlich nicht bewirkt. Der Redner behauptet aber keine Ursache; er nutzt die Geschichte als Parallele, um aus dem Abgelehntwerden auf Genialität zu schließen."},{"option":3,"text":"Fehlende Daten machen eine Theorie nicht schon falsch, das stimmt. Doch der Redner schließt nicht auf Falschheit, sondern aus der Ablehnung auf seine Genialität. Dieser Schluss ist der fehlerhafte."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Affirming the Consequent“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain, Kap. 5","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"32e8e8d9af8b12ab"}},{"id":"qx-d2-023","clusterId":"D","werkstueckRef":"D.3.8","stufe":3,"question":"Welche Rückfrage trifft die Schwäche des Vergleichs am besten?","scenario":"In einer Diskussion über eine neue „Ursache“ einer Krankheit sagt ein Redner: „Die Fachleute lehnen meine These ab. Genau wie bei Galilei: Der wurde von den Gelehrten seiner Zeit verfolgt, und am Ende hatte er recht.“ Du willst prüfen, ob dieser Vergleich trägt.","options":["Welche Vorhersage deiner These zur Krankheitsursache kann jeder unabhängig überprüfen?","Welche Ausbildung hast du, und was hast du bisher zu dieser Krankheit erforscht?","Wer verdient daran, wenn sich deine These zur Ursache verbreitet, und wer verliert?","Wie viele Betroffene haben mit deiner Erklärung der Krankheit schon gute Erfahrungen gemacht?"],"correctIndex":0,"explanation":"Der Vergleich schließt von „Galilei wurde abgelehnt und hatte recht“ auf „ich werde abgelehnt, also habe ich recht“. Das ist ein ungültiger Umkehrschluss: Dass manche Genies abgelehnt wurden, sagt nichts über jeden, der abgelehnt wird, denn auch unzählige falsche Theorien wurden abgelehnt. Ablehnung ist daher kein Beleg, sondern trennt Genie und Irrtum nicht. Entscheidend ist, was die These an Prüfbarem vorlegt. Galilei überzeugte, weil jeder mit einem Fernrohr die Venusphasen und die Jupitermonde sehen konnte. Kepler bestätigte die Monde noch 1610, und die Mathematiker des Jesuitenkollegs in Rom bestätigten 1611 die Venusphasen und die vier Jupitermonde. Die Fachleute prüften also nach und gaben Galilei recht. Verurteilt wurde er erst 1633, und zwar von einer Glaubensbehörde, nicht von einer Fachgemeinschaft. Wer sich auf Galilei beruft, muss deshalb zeigen, was seine eigene These an prüfbaren Belegen hat. Die Rückfrage nach der unabhängig überprüfbaren Vorhersage verlangt genau das und lenkt das Gespräch von der Verfolgung zurück zur Evidenz. Nach Ausbildung oder Verdienst zu fragen betrifft den Redner, nicht den Vergleich, und eine Sammlung guter Erfahrungen ersetzt keine unabhängig überprüfbare Vorhersage.","coreRule":"⚡ Abgelehnt zu werden ist kein Beleg. Entscheidend ist, was andere selbst prüfen können.","beleg":"Werkstück D.3.8 (Kontext & Tiefe, „Die Geschichte wird umgeschrieben“); Fn. gl-d-galileo (Finocchiaro 1989), gl-d-collegio (Favaro 1901, Bd. 11, Nr. 515 und 520, S. 87–88 und 92–93), gl-d-kepler (de Padova 2009). Magini (geprüft 12.10.2026 in Galileo, Le opere, Bd. 10 und 11): Kenntnis der „4 novis planetis“ belegt (Magini an Kepler, 20.4.1610); eigene Aufzeichnung der Monde nicht belegt (Magini an Galilei 23.10.1610: will Linsen erst noch testen; Cigoli an Galilei 23.8.1611: Magini beobachte laut Hörensagen „continuamente“ die vier Jupiterstelle). Halbsatz zu Magini deshalb gestrichen.","status":"entwurf","kurz":"Der Vergleich schließt von „Galilei wurde abgelehnt und hatte recht“ auf „ich werde abgelehnt, also habe ich recht“. Ablehnung trennt Genie und Irrtum nicht; entscheidend ist, was die These an unabhängig Prüfbarem vorlegt.","prueffrage":"Wie viele andere abgelehnte Thesen aus der Geschichte kennst du, die sich am Ende als falsch erwiesen?","rueckmeldung":[{"option":1,"text":"Die Frage nach Ausbildung und Forschung wirkt wie ein fairer Test der Glaubwürdigkeit. Sie zielt aber auf den Redner und nicht auf den Vergleich: Ob die These trägt, zeigen ihre prüfbaren Belege, nicht der Lebenslauf."},{"option":2,"text":"Wer von einer Idee profitiert, wirkt schnell verdächtig. Das sagt aber nichts darüber, ob der Galilei-Vergleich trägt, denn auch eine richtige These kann Gewinner haben. Die Frage betrifft die Motive, nicht die Belege."},{"option":3,"text":"Berichte von Betroffenen klingen nach echter Wirkung. Sie ersetzen aber keine unabhängig überprüfbare Vorhersage, denn gute Erfahrungen können viele andere Gründe haben als die behauptete Ursache."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Favaro, A. (Hg.) (1901): Le Opere di Galileo Galilei, Ed. Nazionale, Bd. 11, Nr. 515 und 520","oeffentlich":false},{"typ":"literatur","kurz":"de Padova, T. (2009): Das Weltgeheimnis. Kepler, Galilei und die Vermessung des Himmels. München: Piper","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"77397e39fd35839a"}},{"id":"qx-d2-024","clusterId":"D","werkstueckRef":"D.3.8","stufe":4,"question":"Was macht diese Argumentation unwiderlegbar?","scenario":"Ein „Heiler“, dem die Zulassung entzogen wurde, schreibt: „Wenn es nicht stimmen würde, würden sie sich nicht so viel Mühe geben, es zu unterdrücken.“","options":["Der Heiler beruft sich auf seine frühere Zulassung und macht diese Autorität zum Beleg, sodass Einwände zur Sache an Gewicht verlieren.","Der Heiler verweist auf die vielen Menschen, die ihm vertrauen, und macht deren Zahl zum Beleg für die Wahrheit seiner Behauptung.","Der Heiler schließt von wenigen geheilten Einzelfällen auf alle Patienten, sodass seine Behauptung auf dünner Grundlage ruht.","Der Heiler wertet jede Reaktion der Gegenseite als Bestätigung: Zustimmung und Widerstand passen gleichermaßen zu seiner These."],"correctIndex":3,"explanation":"Wer Gegenwehr als Beleg wertet, macht seine These unangreifbar: Zustimmung und Ablehnung stützen sie nun gleichermaßen – das ist die vollständige Immunisierung. Eine solche These lässt sich durch keine Reaktion der Gegenseite mehr widerlegen. Die Frage ist also nicht, wie die Kritiker reagieren, sondern welche prüfbare Vorhersage die These macht: Welche Beobachtung würde sie widerlegen? Und was legt der Heiler vor, das andere unabhängig nachprüfen können? Auch Galilei überzeugte nicht durch seine Verfolgung, sondern dadurch, dass jeder durch sein Fernrohr die Jupitermonde und die Venusphasen selbst sehen konnte.","coreRule":"⚡ Eine These, die durch Zustimmung und Ablehnung gleichermaßen bestätigt wird, ist nicht überprüfbar.","beleg":"Werkstück D.3.8 (Anwendung & Relevanz, „Verschwörungsmythen“ und „Pseudomedizin“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Wer Gegenwehr als Beleg wertet, kann nie mehr widerlegt werden: Zustimmung und Ablehnung stützen die These gleichermaßen. Der Fehler liegt darin, keine prüfbare Vorhersage zu machen, die durch eine Beobachtung scheitern könnte.","prueffrage":"Wie würde der Heiler es wohl deuten, wenn die Behörden ihn einfach in Ruhe ließen?","rueckmeldung":[{"option":0,"text":"Frühere Titel können tatsächlich Gewicht in eine Debatte bringen. Im Satz steht aber kein Verweis auf die Zulassung, und selbst eine Berufung auf Autorität würde die These nur schlecht begründen, nicht unwiderlegbar machen."},{"option":1,"text":"Viele Anhänger sagen wenig über die Wahrheit einer Behauptung, das ist ein bekannter Trugschluss. Hier passt er nicht: Der Heiler nennt weder Anhänger noch Vertrauen, und eine unbelegte These bliebe dadurch trotzdem angreifbar."},{"option":2,"text":"Von wenigen Fällen auf alle zu schließen trägt nicht, doch davon steht im Satz nichts. Außerdem ließe sich ein solcher Schluss mit Gegenbeispielen aufdecken, die These bliebe also widerlegbar."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"091635bf8de7f1dc"}},{"id":"qx-d2-025","clusterId":"D","werkstueckRef":"D.3.9","stufe":2,"question":"Was würde am besten klären, ob dein Gegenüber ehrlich nachfragt oder dich nur mit Fragen erschöpfen will?","scenario":"Unter deinem Beitrag zu einem umstrittenen Thema fragt jemand freundlich nach einer Quelle. Du lieferst sie. Die Antwort lautet: „Danke! Und hast du noch eine?“ Du lieferst eine zweite, wieder heißt es „Danke, und noch eine?“ Das wiederholt sich mehrmals, ohne dass je auf den Inhalt der Quellen eingegangen wird.","options":["Beobachten, was nach deiner Antwort geschieht: Arbeitet er mit der Quelle, prüft sie, widerspricht mit Gründen oder ändert etwas, oder folgt nur die nächste Frage?","Auf den Tonfall achten: Bleibt er über alle Runden hinweg freundlich und bedankt sich jedes Mal, spricht das für eine ehrlich gemeinte Nachfrage und gegen bloßes Erschöpfen.","Mitzählen, wie viele Quellen du schon geliefert hast: Je länger die Reihe der Nachfragen wird, desto weniger spricht für ein ehrliches Interesse an der Sache.","Darauf achten, was er verlangt: Wer Belege fordert, zeigt echte Skepsis, wer dagegen nach Meinungen oder Gefühlen fragt, will eher ablenken oder erschöpfen."],"correctIndex":0,"explanation":"Ob eine Nachfrage ehrlich ist, zeigt sich nicht an der einzelnen Frage, sondern an dem, was nach der Antwort geschieht. Wer wirklich verstehen oder prüfen will, geht auf das Gelieferte ein: Er stimmt zu, widerspricht mit Gründen, benennt, was ihn noch nicht überzeugt, oder ändert seine Meinung. Wer nur die nächste Frage stellt, ohne je etwas anzuerkennen, will nicht prüfen, sondern erschöpfen. Das Muster ist als „Sealioning“ bekannt: höfliche Dauerfragen als Belästigungstaktik. Der Tonfall taugt nicht als Kriterium, denn ausgesuchte Höflichkeit gehört zur Taktik, und freundlich war er hier von Anfang an. Auch eine feste Zahl an Nachfragen taugt nicht: Wer sich in eine Quelle vertieft, fragt vielleicht oft, arbeitet aber mit jeder Antwort. Und die Art der Frage unterscheidet ebenfalls nicht, denn auch ein Seelöwe verlangt ständig Belege, gerade für Beiläufiges und Selbstverständliches.","coreRule":"⚡ Prüf, ob dein Gegenüber mit deiner Antwort arbeitet oder nur die nächste Frage stellt.","beleg":"Werkstück D.3.9 (Der Seelöwe im Wohnzimmer; Kontext & Tiefe, „Die Kultur der Nachfrage“; Red Flags; Anti-Denkmuster, Skript 1; Fußnote gl-d-sealioning, Malki 2014)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Entscheidend ist, was nach deiner Antwort geschieht: Wer wirklich prüfen will, geht auf die Quelle ein, widerspricht mit Gründen oder ändert etwas. Wer nur die nächste Frage stellt, will erschöpfen. Einzelne Fragen verraten das nicht.","prueffrage":"Würde sich jemand, der ehrlich fragt und sich gründlich einliest, im Ton oder in der Zahl der Fragen von deinem Gegenüber unterscheiden?","rueckmeldung":[{"option":1,"text":"Freundlichkeit spricht für sich genommen weder für noch gegen echtes Interesse. Höflichkeit gehört bei dieser Taktik oft dazu, und die Person war hier von Anfang an freundlich, ohne je auf den Inhalt einzugehen."},{"option":2,"text":"Eine lange Reihe von Nachfragen ohne Reaktion fällt auf, aber die Zahl selbst entscheidet nichts. Auch wer sich in eine Quelle vertieft, fragt vielleicht oft und arbeitet dennoch mit jeder Antwort. Es kommt darauf an, was jeweils folgt."},{"option":3,"text":"Belege zu fordern ist an sich ein gutes Zeichen, deshalb scheint dieses Kriterium zu tragen. Auch wer nur erschöpfen will, verlangt aber ständig Belege, gerade für Beiläufiges. Die Art der Frage unterscheidet beide nicht."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"},{"typ":"url","kurz":"Malki, D. (2014): „The Terrible Sea Lion“, Wondermark Nr. 1062","oeffentlich":true,"url":"https://wondermark.com/c/1062/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"794df8542cc0334e"}},{"id":"qx-d2-026","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Welche der vier Antworten ist eine legitime Nachfrage und kein Sealioning?","options":["„Danke für die Zusammenfassung. Hast du auch Studien zu anderen Medikamenten gegen dieselben Beschwerden? Ich möchte einfach nur besser verstehen, worum es geht.“","„Danke. Ich habe die Studie gelesen: Die Teilnehmer waren alle erwachsen. Gilt dein Schluss auch für Kinder, und wenn ja, woraus folgt das?“","„Danke für den Link. Kannst du mir noch beweisen, dass diese Studie nichts Falsches enthält? Vorher kann ich deine Aussage leider nicht gelten lassen.“","„Danke! Aber sicher kann man doch nie sein. Und was, wenn auch die nächste Studie zu dem Medikament falsch ist? Du kannst dir doch gar nicht sicher sein, oder?“"],"correctIndex":1,"explanation":"Eine legitime Nachfrage arbeitet mit der erhaltenen Antwort: Sie knüpft an das an, was der Beleg zeigt, und fragt gezielt nach der Lücke. Die anderen Beiträge klingen höflich und für sich nicht unvernünftig, gehen aber nicht auf das Gelieferte ein: Wer nach anderen Medikamenten fragt, wechselt das Thema; wer einen Beweis verlangt, fordert etwas, das niemand erbringen kann; wer nur allgemein zweifelt, sagt nicht, woran. Gerade die höfliche Verpackung macht das gefährlich: Jede einzelne Frage wirkt harmlos, der Schaden wächst mit der Wiederholung, und wer die Geduld verliert, steht als der Unvernünftige da. Der Prüfstein ist nicht die Frage selbst, sondern was nach der Antwort geschieht: Wird mit ihr gearbeitet oder kommt nur die nächste Forderung?","coreRule":"⚡ Eine gute Nachfrage knüpft an deine Antwort an; ein Sealion stellt einfach die nächste Frage.","beleg":"Werkstück D.3.9 (Der Kipppunkt; Der Seelöwe im Wohnzimmer); Fn. gl-d-sealioning (Malki 2014, Wondermark Nr. 1062)","status":"entwurf","scenario":"Du hast unter einem Beitrag zur Wirkung eines Medikaments geschrieben, es habe in einer Studie die Beschwerden verringert. Auf Nachfrage hast du die Studie verlinkt und die Ergebnisse zusammengefasst. Daraufhin kommen vier Antworten.","kurz":"Eine legitime Nachfrage arbeitet mit dem Gelieferten: Sie greift auf, was die Studie zeigt, und fragt gezielt nach der Lücke, hier den Erwachsenen. Die übrigen Beiträge klingen höflich, wechseln aber das Thema, fordern Unmögliches oder zweifeln ohne Ziel.","prueffrage":"Worauf in der verlinkten Studie bezieht sich jede der vier Antworten, und was verlangt sie von dir?","rueckmeldung":[{"option":0,"text":"Der Wunsch, besser zu verstehen, ist an sich nicht verkehrt. Die Frage lässt aber die gelieferte Studie links liegen und wechselt zu anderen Medikamenten, statt an ihre Ergebnisse anzuknüpfen."},{"option":2,"text":"Studien kritisch zu prüfen ist berechtigt. Einen Beweis zu verlangen, dass nichts Falsches darin steht, ist aber nicht zu erbringen und nennt keinen konkreten Mangel. So bleibt jede Antwort ungenügend."},{"option":3,"text":"Dass Ergebnisse nie absolut sicher sind und spätere Studien früheren widersprechen können, stimmt. Der Zweifel nennt aber nicht, woran er sich festmacht, und lässt sich daher mit keiner Antwort ausräumen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2ad6d384d2abe706"}},{"id":"qx-d2-027","clusterId":"D","werkstueckRef":"D.3.9","stufe":4,"question":"Wie reagierst du am besten?","scenario":"Eine Verwandte fragt zu jeder deiner Aussagen „nur mal nach“, erkennt nie etwas an und erzählt hinterher, du seist gereizt gewesen. Du hast schon drei ihrer Fragen mit Belegen beantwortet. Auf keine Antwort ist sie eingegangen: Sie hat weder zugestimmt noch widersprochen noch etwas an ihrer Sicht geändert, sondern jedes Mal die nächste Frage gestellt.","options":["Weiter jede Frage ausführlich beantworten, weil jede unbeantwortete Frage in der Wahrnehmung der anderen als verlorener Punkt zählt.","Ihre Behauptungen im gleichen Umfang hinterfragen, weil so die Beweislast auf beide Seiten verteilt wird und sie selbst Belege liefern muss.","Aussprechen, dass sie auf keine Antwort eingegangen ist, und das Gespräch beenden, weil ein Austausch ohne Gegenseitigkeit kein echtes Gespräch mehr ist.","Ihr eine feste Zahl von Fragen pro Treffen zugestehen, weil so der Aufwand für beide Seiten gerecht begrenzt bleibt."],"correctIndex":2,"explanation":"Wer eine Behauptung belegt hat, hat seine Pflicht erfüllt. Weitere Belege schuldest du erst, wenn dein Gegenüber mit dem Beleg gearbeitet hat: ihn prüft, ihm widerspricht, zustimmt oder benennt, was ihn noch nicht überzeugt. Hier kommt auf jede Antwort nur die nächste Frage, bei geringem Aufwand für sie und hohem für dich. Das Ziel ist dann nicht Erkenntnis, sondern Erschöpfung, und wer irgendwann die Geduld verliert, steht als der Unfreundliche da. Weiter jede Frage zu beantworten wäre der Denkfehler, jede Frage verdiene eine Antwort und jede offene Frage sei ein verlorener Punkt. Gegenfragen und ein festes Fragenkontingent ändern nichts daran, dass deine Verwandte nicht mit den Belegen arbeitet; die Grenze ziehst du, wenn das ausbleibt. Ein Gespräch zu beenden, das keines ist, ist kein Rückzug, sondern ein begründetes Urteil über den Gesprächsverlauf.","coreRule":"⚡ Du schuldest Belege einmal, nicht endlos.","beleg":"Werkstück D.3.9 (Kontext & Tiefe, „Die Asymmetrie des Aufwands“; Anti-Denkmuster, „Bekämpfter Fehler“, „Der Ringrichter“ und Skript 2; Anwendung & Relevanz, „Familie und Freundeskreis“), Fußnote gl-d-sealioning (Malki 2014; Johnson 2017)","status":"entwurf","kurz":"Wer Belege gegeben hat, hat seine Pflicht erfüllt; weitere schuldest du erst, wenn sie mit ihnen arbeitet. Folgt auf jede Antwort nur die nächste Frage, darfst du das benennen und aufhören, statt jede offene Frage für einen verlorenen Punkt zu halten.","prueffrage":"Wie viel Mühe hat sie jede ihrer Fragen gekostet, und wie viel Mühe hat dich jede deiner Antworten gekostet?","rueckmeldung":[{"option":0,"text":"Jede Frage zu beantworten wirkt höflich, und Schweigen kann tatsächlich wie ein verlorener Punkt aussehen. Doch kein Punktestand entscheidet hier, sondern ob sie mit deinen Belegen arbeitet, und das tut sie nicht: Der Aufwand liegt allein bei dir."},{"option":1,"text":"Gegenfragen wirken fair, denn wer etwas behauptet, schuldet Belege. Am Kern ändern sie aber nichts: Sie arbeitet nicht mit deinen Belegen, und ein Hin und Her aus Fragen macht daraus noch kein Gespräch."},{"option":3,"text":"Ein Kontingent begrenzt den Aufwand und klingt gerecht. Es lässt aber den Kern bestehen: Auch innerhalb der erlaubten Fragen würde sie nicht auf deine Antworten eingehen, und dann ist die Zahl der Fragen weniger entscheidend als die fehlende Gegenseitigkeit."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d089c26b080f9244"}},{"id":"qx-d2-028","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Warum trifft die Antwort der Nutzerin den Kern dieser Äußerung?","scenario":"Unter einem Beitrag über ein neues Impfprogramm schreibt jemand: „Ist es nicht seltsam, dass genau jetzt so viele Menschen krank werden? Ich frage ja nur.“ Eine Quelle oder Zahl nennt die Person nicht. Eine andere Nutzerin antwortet: „Das ist keine Frage, das ist eine Behauptung.“","options":["Die Frage unterstellt einen Zusammenhang zwischen Impfprogramm und Erkrankungen, ohne ihn zu belegen, und das legt die Nutzerin als verdeckte Behauptung offen.","Die Frage legt den Verantwortlichen des Impfprogramms eine Position in den Mund, die diese nie vertreten haben, und das legt die Nutzerin als Strohmann offen.","Die Frage greift die Verantwortlichen des Impfprogramms persönlich an statt ihre Entscheidungen, und das legt die Nutzerin als Angriff auf die Person offen.","Die Frage stellt nur zwei Möglichkeiten zur Wahl, Impfprogramm oder gesunde Bevölkerung, und das legt die Nutzerin als falsches Dilemma offen."],"correctIndex":0,"explanation":"Die Äußerung ist grammatisch eine Frage, legt aber eine Behauptung nahe: einen Zusammenhang zwischen dem Impfprogramm und den Erkrankungen. Solche Fragen sind verkleidete Behauptungen („Ist es nicht seltsam, dass …?“): Sie lassen sich streuen, ohne belegt werden zu müssen. Der Fragende kann sich bei Widerspruch darauf zurückziehen, er habe ja nur gefragt. Wer so antwortet, wie die Nutzerin es tut, legt die versteckte Behauptung frei, und erst dann lässt sie sich prüfen: Was genau wird nahegelegt, und wofür gibt es Belege? Ein ehrlicher Fragender arbeitet dagegen mit der Antwort: Er prüft sie, widerspricht ihr oder benennt, was ihn noch nicht überzeugt.","coreRule":"⚡ Prüfe bei jeder Frage, welche Behauptung sie mitführt, und wer diese Behauptung belegen müsste.","beleg":"Werkstück D.3.9 (Kontext & Tiefe, letzter Absatz, letzter Satz „Ein Verwandter ist das ‚Ich stelle doch nur Fragen‘ …“)","status":"entwurf","kurz":"Grammatisch ist es eine Frage, sie legt aber einen Zusammenhang zwischen Impfprogramm und Erkrankungen nahe, den niemand belegen muss. Die Nutzerin macht diese verdeckte Behauptung sichtbar, erst dann lässt sie sich prüfen.","prueffrage":"Würde sich an der Wirkung des Beitrags etwas ändern, wenn derselbe Satz ohne Fragezeichen dastünde?","rueckmeldung":[{"option":1,"text":"Ein Strohmann verzerrt die Position eines Gegenübers. Hier wird den Verantwortlichen aber nichts in den Mund gelegt, die Äußerung deutet nur einen Zusammenhang an, den sie nicht belegt."},{"option":2,"text":"Ein Angriff auf die Person richtet sich gegen Menschen statt gegen ihre Argumente. In der Äußerung werden aber keine Personen angegriffen, sie spricht nur über den Zeitpunkt der Erkrankungen."},{"option":3,"text":"Ein falsches Dilemma erzwingt eine Wahl zwischen nur zwei Möglichkeiten. Die Äußerung stellt aber keine Alternativen zur Wahl, sondern legt in Frageform einen Zusammenhang nahe, ohne ihn zu belegen."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard (nur Teilaspekt)","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f2f7fff65295d6ea"}},{"id":"qx-d2-029","clusterId":"D","werkstueckRef":"D.4.1","stufe":1,"question":"Welche Rückfrage prüft die Behauptung am besten?","scenario":"Auf der Webseite einer Praxis steht: „Unsere Behandlung löst Blockaden im Energie-Fluss und bringt die Schwingung Ihres Körpers zurück in die Harmonie. Spüren können das allerdings nur besonders sensitive Menschen; technische Geräte registrieren es nicht.“ Eine Freundin überlegt, dafür 400 Euro auszugeben.","options":["„In welcher Einheit misst du diese Energie, und mit welchem Instrument kann man sie auch ohne besonders sensitive Menschen nachweisen?“","„Welche Ausbildung und Zulassung haben die Behandelnden, und sind sie in einem anerkannten Berufsverband organisiert?“","„Mit welchen Nebenwirkungen ist zu rechnen, und kann man die Behandlung abbrechen und sich das Geld erstatten lassen?“","„Wie teuer ist eine einzelne Sitzung im Vergleich zu anderen Praxen in der Gegend, und kann man in Raten zahlen?“"],"correctIndex":0,"explanation":"In der Physik ist Energie eine klar definierte, messbare Größe: Man gibt sie in Joule oder Kilowattstunden an und kann sie mit Instrumenten nachweisen. Hier wird dasselbe Wort zur vagen Allzweck-Erklärung: Es gibt keine Einheit, kein Messgerät, und wahrnehmbar soll es nur für „Sensitive“ sein. Dadurch lässt sich die Behauptung nie widerlegen, denn jeder Misserfolg ließe sich mit mangelnder Sensitivität erklären. Die Frage nach Einheit und Instrument zwingt dazu, den Begriff messbar zu machen oder zuzugeben, dass er nur bildlich gemeint ist. Fragen nach Ausbildung, Nebenwirkungen oder Preis sind beim Kauf einer Behandlung vernünftig, klären aber nicht, ob das behauptete Phänomen überhaupt existiert.","coreRule":"⚡ Frag bei „Energie“ und „Schwingung“ nach Einheit und Messgerät.","beleg":"Werkstück D.4.1 (Der kaputte Fernseher; Kontext & Tiefe)","status":"entwurf","kurz":"Der Begriff „Energie“ wird hier ohne Einheit und Messgerät benutzt, und nur „Sensitive“ sollen ihn spüren. Dadurch lässt sich jeder Misserfolg wegerklären. Die Frage nach Einheit und Instrument macht die Behauptung prüfbar.","prueffrage":"Woran könnte man erkennen, dass die Behauptung falsch ist, wenn jeder Misserfolg erklärbar bleibt?","rueckmeldung":[{"option":1,"text":"Nach Qualifikation zu fragen ist beim Kauf einer Behandlung vernünftig, und eine Zulassung schafft etwas Sicherheit. Ob der behauptete Energie-Fluss überhaupt existiert, sagt sie aber nicht, denn auch für unbelegte Verfahren gibt es Ausbildungen und Verbände."},{"option":2,"text":"Wer nach Nebenwirkungen und Erstattung fragt, schützt sich vor einem Verlust, und das ist sinnvoll. Die Kernbehauptung bleibt dabei ungeprüft: Eine Behandlung kann risikoarm und rückzahlbar sein, ohne dass ein Energie-Fluss existiert."},{"option":3,"text":"Ein Preisvergleich und die Frage nach Ratenzahlung helfen, das Geld klug einzusetzen. Sie sagen aber nichts darüber, ob die Wirkung existiert: Eine unbelegte Behauptung wird durch einen niedrigen Preis nicht belegt und durch einen hohen nicht widerlegt."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“ (Stand 25.02.2021)","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ernst, E. (2023): Vorsicht Heilpraktiker: Eine kritische Analyse. Berlin: Springer, Abschn. 13.4 „Bioresonanz“ (DOI 10.1007/978-3-662-66742-2)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5846f7ada1c53862"}},{"id":"qx-d2-030","clusterId":"D","werkstueckRef":"D.4.1","stufe":2,"question":"Welche Rückfrage prüft diese Werbeaussage am wirksamsten?","scenario":"Auf einer Website steht: „Unser Kristall sendet starke Heilenergie aus und stellt die richtige Frequenz Ihrer Organe wieder her.“ Eine Messgröße oder Einheit wird nirgends genannt.","options":["„Wie viele Organe sind von dieser Wirkung betroffen, und wie lange hält sie an?“","„In welcher Einheit messen Sie diese Energie, und mit welchem Instrument weisen Sie sie nach?“","„Aus welchem Material besteht der Kristall, und aus welchem Land stammt er ursprünglich?“","„Gibt es eine Rückgabegarantie, falls man die Wirkung nicht bemerkt, und wie lange gilt sie?“"],"correctIndex":1,"explanation":"Der Anbieter borgt sich Begriffe aus der Physik, ohne ihre messbare Bedeutung mitzuliefern. Energie lässt sich in Joule angeben, eine Strahlungsleistung in Watt, eine Frequenz in Hertz, und all das lässt sich mit Instrumenten nachweisen. Die Frage nach Einheit und Messgerät verlangt genau diesen Nachweis und zeigt, ob mehr als eine Metapher dahintersteckt.","coreRule":"⚡ Keine Einheit, kein Messgerät, keine Physik.","beleg":"Werkstück D.4.1 (Kontext & Tiefe, „Die wissenschaftliche Bedeutung“; Red Flags)","status":"entwurf","kurz":"Einheit und Messinstrument zu erfragen verlangt den Nachweis, dass die Energie überhaupt messbar existiert. Wer stattdessen nach Umfang, Dauer oder Rückgabe fragt, übernimmt die Behauptung zunächst als gegeben.","prueffrage":"Welche Antwort könnte der Anbieter auf eine Frage geben, ohne dass sich irgendetwas an ihr überprüfen ließe?","rueckmeldung":[{"option":0,"text":"Organzahl und Wirkdauer sind für Käufer naheliegende Fragen. Sie setzen die Wirkung aber schon voraus und fragen nur nach ihrem Umfang, nicht danach, ob es die behauptete Energie überhaupt gibt."},{"option":2,"text":"Material und Herkunft sind als Kaufinformation nützlich. Sie sagen aber nichts darüber, ob der Kristall Heilenergie aussendet, die Aussage selbst bleibt dadurch ungeprüft."},{"option":3,"text":"Eine Rückgabegarantie schützt vor finanziellem Verlust und ist für Käufer sinnvoll. Ob es die behauptete Energie gibt, klärt sie jedoch nicht, die Behauptung bleibt so unüberprüft stehen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“ (Stand 25.02.2021)","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"},{"typ":"url","kurz":"Ernst, E. (2020): „Bioresonance: a new and hilariously ingenious study“, edzardernst.com, 09.04.2020","oeffentlich":true,"url":"https://edzardernst.com/2020/04/bioresonance-a-new-and-hilariously-ingenious-study/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"60bb3ea61ecda22d"}},{"id":"qx-d2-031","clusterId":"D","werkstueckRef":"D.4.1","stufe":3,"question":"Welche dieser drei Situationen ist problematisch und warum?","options":["Situation 1, weil „Energie“ in der Physik fest definiert ist und die Verwendung des Wortes für ein Raumgefühl Zuhörer deshalb in die Irre führt.","Situation 2, weil ein bildhaftes Wort als messbare Größe ausgegeben wird und daraus Diagnosen und teure Behandlungen folgen.","Situation 3, weil „Vibes“ auf eine Schwingung verweist, die sich ohne Messgerät nicht belegen lässt, sodass die Aussage unseriös wirkt.","Alle drei Situationen, weil in jeder ein Wort aus der Physik für etwas benutzt wird, das niemand gemessen hat und das nur so klingt."],"correctIndex":1,"explanation":"Eine Metapher wie „gute Energie“ oder „gute Vibes“ beschreibt ein Gefühl und erhebt keinen Messanspruch. Sie schadet niemandem, solange alle verstehen, dass sie bildlich gemeint ist. Problematisch wird es, wenn dieselbe Redeweise als buchstäbliche, physikalische Realität auftritt: Dann müsste sich die behauptete „Frequenz“ in einer physikalischen Einheit und mit einem Instrument messen lassen. Hängen daran auch noch medizinische Diagnosen und teure Behandlungen, kann ein falscher Messanspruch echten Schaden anrichten. Entscheidend ist also nicht, ob ein Fachwort außerhalb der Fachsprache auftaucht, sondern ob aus einem Bild ein Messwert gemacht wird, auf den Entscheidungen mit Konsequenzen gebaut werden.","coreRule":"⚡ Eine Metapher ist harmlos, bis sie als Messwert verkauft wird.","beleg":"Werkstück D.4.1 (Der Kipppunkt)","status":"entwurf","scenario":"Drei Situationen:\\n(1) Eine Freundin betritt dein neues Wohnzimmer und sagt: „Der Raum hat eine richtig gute Energie.“\\n(2) Ein Anbieter bewirbt ein Gerät, das die „Schwingungsfrequenz“ deiner Organe misst, und erklärt daraus eine Diagnose samt teurem Behandlungsplan.\\n(3) Ein Kollege sagt nach einem gelungenen Workshop: „Die Vibes waren heute super.“","kurz":"Problematisch ist Situation 2: Dort wird aus einem Bild eine messbare Größe, und auf sie stützen sich Diagnose und teure Behandlung. Ein Physikwort allein ist kein Fehler; „Energie“ und „Vibes“ beschreiben nur ein Gefühl und behaupten keine Messung.","prueffrage":"Was folgt in jeder der drei Situationen auf die Äußerung?","rueckmeldung":[{"option":0,"text":"Es stimmt, dass „Energie“ in der Physik fest definiert ist. Die Freundin behauptet aber keine Messung, sondern beschreibt ein Raumgefühl, und alle verstehen das bildlich. Verwirrend wäre es erst, wenn jemand daraus einen messbaren Wert machte."},{"option":2,"text":"„Vibes“ klingt nach Schwingung, ist hier aber nur ein Wort für die Stimmung im Workshop. Niemand behauptet, etwas gemessen zu haben, also gibt es nichts zu belegen. Bildhafte Rede wirkt nicht schon deshalb unseriös, weil sie ein Fachwort anklingen lässt."},{"option":3,"text":"In allen drei Fällen klingt ein Physikwort an, und gemessen hat wohl niemand etwas. Der Unterschied liegt darin, dass nur eine Situation eine Messung behauptet und darauf Diagnosen und Kosten baut. Ein Fachwort im Alltag ist für sich noch kein Problem."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“ (Stand 25.02.2021)","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"152aefb0bd417f36"}},{"id":"qx-d2-032","clusterId":"D","werkstueckRef":"D.4.1","stufe":4,"question":"Ein Anbieter wirbt: „Unser Gerät misst die Frequenzen deiner Organe und deckt Disharmonien auf.“ Du darfst das Gerät aufschrauben und die Messtechnik prüfen. Was findest du bei einem Gerät, dessen Werbeversprechen sich nur als Kundentäuschung erklären lässt?","options":["Eine einfache Schaltung, die die elektrische Leitfähigkeit der Haut misst, ohne irgendetwas über einzelne Organe zu erfassen.","Ein Elektrodenpaar, das die elektrischen Herzströme ableitet und daraus Herzfrequenz und Rhythmus des Herzens berechnet.","Ein Mikrofon samt Auswertung, das Herz- und Atemgeräusche aufnimmt und deren Frequenzen für beide Organe getrennt anzeigt.","Elektroden am Kopf, die die Hirnströme ableiten und deren Frequenzbänder getrennt auswerten und anzeigen."],"correctIndex":0,"explanation":"Hinter dem Wort „Frequenz“ steckt hier keine Organmessung. Bioresonanzgeräte bestehen im Wesentlichen aus einer Schaltung, die die Leitfähigkeit der Haut misst (Ernst 2023), und eine Hautleitfähigkeit sagt nichts über einzelne Organe; „Organfrequenzen“ und „Disharmonien“ sind damit keine Messwerte, sondern Deutung. Die übrigen Funde würden tatsächlich etwas an Herz, Lunge oder Gehirn erfassen und das Versprechen zumindest teilweise einlösen, wären also keine bloße Täuschung, sondern Messtechnik, wie sie auch in der Medizin vorkommt. Die Prüffrage lautet immer: Was misst das Gerät tatsächlich, in welcher Einheit, mit welchem Sensor, und wie wurde geprüft, dass der Messwert zum behaupteten Organ gehört? Ein bloß geliehenes Wort wie „Frequenz“ verleiht dem Gerät nur den Anschein von Wissenschaft.","coreRule":"⚡ Frag, was das Gerät tatsächlich misst, nicht, was der Prospekt behauptet.","beleg":"Werkstück D.4.1 (Anwendung & Relevanz, „In der Pseudomedizin“); Fn. gl-d-bioresonanz (Ernst 2023, Abschn. 13.4, S. 120)","status":"entwurf","scenario":"","kurz":"Eine Schaltung, die nur Hautleitfähigkeit misst, sagt nichts über einzelne Organe aus. „Organfrequenzen“ sind dann keine Messwerte, sondern Deutung. Das Wort „Frequenz“ gibt dem Gerät bloß den Anschein von Wissenschaft.","prueffrage":"Welche Größe zeigt das Gerät an, in welcher Einheit, und wie wurde belegt, dass der Wert zu einem bestimmten Organ gehört?","rueckmeldung":[{"option":1,"text":"Herzströme abzuleiten ist echte Messtechnik, wie sie auch die Medizin nutzt. Ein solcher Fund würde das Versprechen für das Herz zumindest teilweise einlösen und wäre damit keine bloße Täuschung."},{"option":2,"text":"Herz- und Atemgeräusche aufzunehmen erfasst tatsächlich etwas an Herz und Lunge, auch das kennt die Medizin. Das Versprechen wäre damit zumindest teilweise eingelöst, also nicht allein Kundentäuschung."},{"option":3,"text":"Hirnströme mit getrennten Frequenzbändern auszuwerten ist echte, medizinisch etablierte Messtechnik am Gehirn. Das löst das Versprechen zumindest teilweise ein und wäre daher keine reine Täuschung."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ernst, E. (2020): „Bioresonance: a new and hilariously ingenious study“, edzardernst.com, 09.04.2020","oeffentlich":true,"url":"https://edzardernst.com/2020/04/bioresonance-a-new-and-hilariously-ingenious-study/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ernst, E. (2023): Vorsicht Heilpraktiker: Eine kritische Analyse. Berlin: Springer, Abschn. 13.4 „Bioresonanz“ (DOI 10.1007/978-3-662-66742-2)","oeffentlich":false},{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"435d344723845fe1"}},{"id":"qx-d2-033","clusterId":"D","werkstueckRef":"D.4.2","stufe":1,"question":"Welche Frage prüft die Behauptung des Verkäufers am besten?","scenario":"Ein Verkäufer preist einen rostigen Kleinwagen an: „Das ist ein Quanten-Auto. Denk mit deinem Quantenbewusstsein an dein Ziel, dann kollabiert die Wahrscheinlichkeitswelle des Motors zu deinen Gunsten.“","options":["Welche von Fachleuten geprüfte Messung zeigt, dass ein Quanteneffekt den Motor dieses Autos beeinflusst?","Welche Belege zeigt der Verkäufer für Wartung und Zustand des Motors, und wann war der Wagen zuletzt beim TÜV?","Was kostet der rostige Kleinwagen, und was kosten vergleichbare Modelle ohne Quantenversprechen auf dem Markt?","Wie lange verkauft der Verkäufer schon Gebrauchtwagen, und wie viele Kunden haben sich bisher beschwert?"],"correctIndex":0,"explanation":"Der Verkäufer benutzt Begriffe aus der Quantenphysik („Wahrscheinlichkeitswelle“, „Kollaps“). Deren Gesetze gelten zwar auch für große Objekte, doch Überlagerungen zerfallen bei einem Auto durch die ständige Wechselwirkung mit der Umgebung so schnell, dass man sie nicht beobachten kann (Dekohärenz); sichtbar werden sie nur an gut abgeschirmten Systemen wie einzelnen Teilchen, Atomen oder Molekülen. Die Quantenbegriffe dienen hier als Wissenschafts-Anstrich: Weil Laien die echte Quantenphysik kaum nachprüfen können, lässt sich ihr Vokabular als Schutzschild gegen Kritik missbrauchen. Wer die Behauptung prüfen will, muss deshalb nach einem Nachweis für den behaupteten Effekt fragen. Fragen nach Wartung und TÜV sind beim Autokauf vernünftig, sagen aber nichts über den Quanteneffekt. Der Preisvergleich klärt, ob der Wagen sein Geld wert ist, nicht ob die Behauptung stimmen kann. Die Erfahrung des Verkäufers und Beschwerden von Kunden sagen etwas über ihn, nicht über seine Behauptung.","coreRule":"⚡ Wenn ein Alltagsding „Quanten“ im Namen trägt, frag nach der Studie, die den Quanteneffekt messbar nachweist.","beleg":"Werkstück D.4.2 (Der erleuchtete Autoverkäufer; Kernidee)","status":"entwurf","kurz":"Wer die Behauptung prüfen will, muss nach einem Nachweis für den behaupteten Effekt fragen. Quantenbegriffe wirken wissenschaftlich, doch bei einem Auto zerfallen Überlagerungen durch die Umgebung so schnell, dass man sie nicht beobachten kann.","prueffrage":"Was müsste am Auto anders ablaufen, wenn du an dein Ziel denkst, als wenn du es nicht tust?","rueckmeldung":[{"option":1,"text":"Wartung und TÜV sind beim Autokauf eine vernünftige Frage und zeigen, in welchem Zustand der Motor wirklich ist. Über den behaupteten Quanteneffekt sagen sie jedoch nichts, den prüfen sie nicht."},{"option":2,"text":"Der Preisvergleich zeigt, ob der Wagen sein Geld wert ist, und das ist beim Kauf wichtig. Ob die Behauptung vom Quanteneffekt stimmen kann, bleibt dabei aber ungeprüft."},{"option":3,"text":"Wie lange der Verkäufer im Geschäft ist und wie viele Kunden sich beschwert haben, sagt etwas über ihn und seinen Ruf. Die Behauptung selbst wird dadurch weder gestützt noch widerlegt."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715 (DOI 10.1103/RevModPhys.75.715), arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"},{"typ":"url","kurz":"Universität Wien, Quantum Science (Arndt-Gruppe): „2.000 Molecules exist at two places at once“, 09.12.2019","oeffentlich":true,"url":"https://quantum.univie.ac.at/news/details-news/news/2000-molecules-exist-at-two-places-at-once/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2b7aaeef0053e719"}},{"id":"qx-d2-034","clusterId":"D","werkstueckRef":"D.4.2","stufe":2,"question":"Welche Gegenfrage prüft die Behauptung des Coaches am besten?","scenario":"Ein Coach sagt, durch „Quantenverschränkung“ und die Kraft deiner Absicht könnest du deine Krankheit „zum Kollabieren bringen“. Du willst herausfinden, ob an der Behauptung etwas dran ist.","options":["Welche Fachgesellschaft hat dich als Quantenheiler zertifiziert, und wie lange arbeitest du schon in diesem Beruf?","Welche Studie zeigt, dass ein solcher Quanteneffekt im menschlichen Körper eine messbare Wirkung hat, und wo ist sie veröffentlicht?","Welche Rechnung zur Schrödinger-Gleichung für ein Elektron kannst du vorführen, und was zeigt sie über dein Wissen?","Welche Erfahrungsberichte früherer Klienten sprechen für deine Methode, und wo kann ich ihre Bewertungen nachlesen?"],"correctIndex":1,"explanation":"Geprüft werden muss die Behauptung, nicht die Person. Quanteneffekte wie Verschränkung oder Überlagerung sind real, lassen sich aber nur an gut abgeschirmten Systemen beobachten. In größeren Systemen zerfallen die Überlagerungen durch die ständige Wechselwirkung mit der Umgebung so schnell, dass man sie nicht beobachten kann (Dekohärenz). Ob so ein Effekt im menschlichen Körper etwas heilt, lässt sich deshalb nur mit einer begutachteten Studie am konkreten System belegen. Für Heilversprechen dieser Art gibt es eine solche Studie nicht. Ein Zertifikat oder Berufsjahre helfen nicht weiter: Eine Quelle, die nur ein spiritueller Guru oder Coach ist, liefert keinen Nachweis am System. Eine Rechenvorführung zeigt ebenfalls nicht, ob die Behauptung zutrifft. Erfahrungsberichte beantworten die Kernfrage nicht, ob ein Quanteneffekt im Körper eine messbare Wirkung hat. Sie liefern keinen Nachweis am konkreten System.","coreRule":"⚡ Verlang den Nachweis am konkreten System, nicht den Titel der Person.","beleg":"Werkstück D.4.2 (Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"Ob ein Quanteneffekt im Körper etwas heilt, zeigt nur eine begutachtete Studie am konkreten System, und für solche Heilversprechen gibt es keine. Der naheliegende Fehler ist, die Person zu prüfen statt die Behauptung.","prueffrage":"Woran ließe sich von außen erkennen, ob deine Absicht tatsächlich etwas an der Krankheit verändert hat?","rueckmeldung":[{"option":0,"text":"Nach der Qualifikation zu fragen, klingt sachlich, denn Fachwissen kann ein Hinweis sein. Es prüft aber die Person und nicht die Behauptung: Ein Zertifikat oder Berufsjahre belegen nicht, dass der Effekt im Körper existiert."},{"option":2,"text":"Quantenphysik hat tatsächlich mit Rechnungen zu tun, deshalb liegt diese Probe nahe. Sie zeigt aber nur, was jemand rechnen kann. Ob im Körper ein Quanteneffekt eine Krankheit beeinflusst, sagt eine Rechnung für ein einzelnes Elektron nicht."},{"option":3,"text":"Erfahrungsberichte wirken greifbar, weil dort echte Menschen sprechen. Sie sind aber Einzelfälle ohne Vergleich und ohne Messung und zeigen nicht, ob ein Quanteneffekt im Körper messbar wirkt."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715, arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4d931a4ece86b230"}},{"id":"qx-d2-035","clusterId":"D","werkstueckRef":"D.4.2","stufe":3,"question":"Ein Esoterik-Coach sagt: „Quantenphysik gilt nur für Atome. Ein Fußball ist nie an zwei Orten gleichzeitig, also ist klar, dass Quantengesetze bei großen Objekten einfach aufhören. Meine Kunden brauchen sich um Quantenphysik im Alltag also keine Sorgen zu machen.“ Du willst ihm nicht nur die falsche Schlussfolgerung nachweisen, sondern auch erklären, warum der Ball sich trotzdem klassisch verhält. Welche Erklärung ist die sparsamste und zugleich sachlich haltbar?","options":["Die Gesetze gelten auch für den Ball, doch ab einer bestimmten Masse lässt ein zusätzliches Naturgesetz die Überlagerung von selbst zusammenbrechen.","Die Gesetze gelten auch für den Ball, doch seine Überlagerung bleibt dauerhaft bestehen und ist nur zu fein, als dass ein Gerät sie messen könnte.","Die Gesetze gelten auch für den Ball, doch die Umgebung lässt seine Überlagerung so schnell zerfallen, dass man sie nicht beobachten kann.","Die Gesetze gelten auch für den Ball, doch sobald jemand hinsieht, beendet dessen Bewusstsein die Überlagerung und legt den Ball auf einen Ort fest."],"correctIndex":2,"explanation":"Die Quantenphysik beschränkt sich nicht auf das Subatomare: Überlagerung wurde schon an Molekülen aus rund 2.000 Atomen nachgewiesen (Fein u. a. 2019). Eine Grenze, an der die Gesetze enden, ist also nicht belegt. Dass der Ball trotzdem klassisch wirkt, erklärt die Dekohärenz: Große Objekte stehen ständig in Wechselwirkung mit ihrer Umgebung, wodurch ihre Überlagerungen so schnell zerfallen, dass man sie nicht beobachten kann. Dieselben Gesetze erzeugen also das klassische Verhalten. Die Erklärung kommt ohne Sonderregel für große Dinge aus und ist deshalb die sparsamste. Das Bewusstsein des Beobachters klingt nach Quantenphysik, ist aber die esoterische Umdeutung des Beobachtereffekts und gilt als Pseudowissenschaft.","coreRule":"⚡ Wenn ein Effekt im Alltag fehlt, schließe nicht auf „Gesetz endet hier“. Frage, welcher Mechanismus ihn unbeobachtbar macht. Bei Quanteneffekten zerstört die Umgebung die Überlagerung großer Objekte so schnell, dass sie unbeobachtbar bleibt.","beleg":"Werkstück D.4.2 (Kontext & Tiefe, „Die wissenschaftliche Bedeutung“); Fn. gl-d-quanten (Fein u. a. 2019, Nature Physics 15), gl-d-dekohaerenz (Zurek 2003, Reviews of Modern Physics 75, S. 715–775)","status":"entwurf","scenario":"","kurz":"Der Ball folgt denselben Gesetzen wie Atome. Weil er ständig mit seiner Umgebung wechselwirkt, zerfällt jede Überlagerung blitzschnell, daher wirkt er klassisch. Aus „nie an zwei Orten“ folgt kein Ende der Gesetze, und eine Sonderregel braucht es nicht.","prueffrage":"Wurde Überlagerung schon an Objekten nachgewiesen, die deutlich größer sind als einzelne Atome?","rueckmeldung":[{"option":0,"text":"Eine Massengrenze klingt klar und übersichtlich, und solche Kollapsmodelle werden tatsächlich diskutiert. Belegt sind sie aber nicht, und sie sind gar nicht nötig, weil die Umgebung das klassische Verhalten schon ohne Zusatzgesetz erklärt."},{"option":1,"text":"Dass sich Überlagerungen bei großen Objekten kaum messen lassen, stimmt, und das klingt nach bloßer Messgenauigkeit. Der Grund ist aber ein anderer: Die Überlagerung bleibt nicht bestehen, ihre Information fließt in die Umgebung ab."},{"option":3,"text":"Das Wort „Beobachter“ legt nahe, dass es auf das Hinsehen und das Bewusstsein ankommt. Entscheidend ist aber die Wechselwirkung mit der Umgebung, die auch ohne Menschen stattfindet. Das Bewusstsein als Auslöser ist eine esoterische Umdeutung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Universität Wien, Quantum Science (Arndt-Gruppe): „2.000 Molecules exist at two places at once“, 09.12.2019 (zu Fein u. a. 2019)","oeffentlich":true,"url":"https://quantum.univie.ac.at/news/details-news/news/2000-molecules-exist-at-two-places-at-once/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fein, Y. Y. u. a. (2019): „Quantum superposition of molecules beyond 25 kDa“, Nature Physics 15, 1242–1245","oeffentlich":false,"doi":"10.1038/s41567-019-0663-9"},{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715, arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3c6d49f7407c2ff7"}},{"id":"qx-d2-036","clusterId":"D","werkstueckRef":"D.4.2","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Eine Anbieterin von „Quantenheilung“ sagt: „Quantenphysik versteht kaum jemand richtig, du nicht und ich auch nicht ganz. Also kannst du nicht ausschließen, dass meine Deutung stimmt. Es könnte also wirken.“","options":["Aus dem Umstand, dass niemand etwas sicher ausschließen kann, wird abgeleitet, dass es plausibel sei; Nichtwissen gilt als Beleg.","Die Anbieterin greift den Kritiker als Person an, statt auf dessen Gründe einzugehen, und schränkt dadurch das Gespräch ein.","Die Anbieterin setzt die zu beweisende Behauptung bereits als Voraussetzung ein und dreht sich mit ihrer Begründung im Kreis.","Die Anbieterin beruft sich auf eine Fachautorität, die ihre Deutung nie bestätigt hat, und hält dadurch die Debatte offen."],"correctIndex":0,"explanation":"Der Schluss lautet: „Wir verstehen es nicht, also könnte meine Deutung wahr sein.“ Das ist ein Argument aus Unwissenheit. Aus Nichtwissen wird hier Plausibilität gemacht, obwohl Nichtwissen kein Beleg ist. Die Komplexität des Themas wird als Schutzschild gegen Kritik missbraucht. Wirkt etwas, muss sich das belegen lassen, etwa durch eine Studie, die an einem biologischen System eine messbare Wirkung zeigt. Die Schwierigkeit des Themas ersetzt diesen Beleg nicht. Zudem lassen sich Quanteneffekte nur an gut abgeschirmten, kleinen Systemen beobachten, weil die Umgebung Überlagerungen großer Objekte sehr schnell zerstört (Dekohärenz).","coreRule":"⚡ „Das kann man nicht widerlegen“ ist kein Beleg.","beleg":"Werkstück D.4.2 (Kontext & Tiefe, „Die pseudowissenschaftliche Umdeutung“; Verweis auf Werkstück B.11, Argument aus Unwissenheit)","status":"entwurf","kurz":"Dass niemand etwas ganz ausschließen kann, macht es nicht plausibel: Nichtwissen ist kein Beleg. Ein Wirkungsnachweis müsste messbar sein, etwa an einem biologischen System. Das schwierige Thema ersetzt ihn nicht, es schützt nur vor Kritik.","prueffrage":"Was ließe sich mit dem Satz „du kannst es nicht ausschließen“ sonst noch alles begründen?","rueckmeldung":[{"option":1,"text":"„Du nicht“ kann wie ein Seitenhieb klingen, doch die Anbieterin schließt sich mit „ich auch nicht ganz“ selbst ein und greift niemanden an. Fehlerhaft ist der Schluss vom allgemeinen Nichtverstehen auf Plausibilität."},{"option":2,"text":"Ein Kreis wäre es, wenn die Behauptung schon in ihrer Begründung steckte. Hier folgt „es könnte wirken“ aber aus dem Nichtverstehen. Die Begründung trägt nicht, sie läuft nur nicht im Kreis."},{"option":3,"text":"Eine Fachautorität nennt die Anbieterin nicht. Sie sagt nur, kaum jemand verstehe Quantenphysik richtig, und macht aus diesem Nichtwissen ein Argument für ihre Deutung."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Appeal to Ignorance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715, arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"33c36fbb57778b1a"}},{"id":"qx-d2-037","clusterId":"D","werkstueckRef":"D.4.3","stufe":1,"question":"Ein Händler sagt: „Unser Vitamin C ist rein natürlich, aus handgepflückten Kirschen, und deshalb besser für den Körper als die Tablette aus dem Labor.“ Beide Produkte enthalten dasselbe Molekül. Welche Erwiderung prüft die Behauptung am besten?","scenario":"Du stehst im Reformhaus. Der Händler zeigt dir zwei gleich aussehende Pillen: Pille A mit „natürlichem“ Vitamin C aus Acerolakirschen für den doppelten Preis, Pille B mit synthetischer Ascorbinsäure aus dem Labor. Auf beiden Packungen steht als Wirkstoff dasselbe Molekül, C₆H₈O₆.","options":["Auf das gleiche Molekül C₆H₈O₆ verweisen: Der Körper kann beide nicht unterscheiden, eine bessere Wirkung müsste der Händler mit Studien zur Aufnahme belegen.","Beim Händler klären, ob die Kirschen von Hand gepflückt wurden: Stimmt das, spricht es für eine bessere Wirkung, und die Behauptung des Händlers wäre gestützt.","Die Milligramm Vitamin C beider Packungen vergleichen: Enthält Pille A mehr, wirkt sie stärker, und die Behauptung des Händlers wäre damit bestätigt.","Klären, ob „natürlich“ für Pille A rechtlich geschützt ist: Trifft das zu, wäre damit belegt, dass sie dem Körper besser bekommt."],"correctIndex":0,"explanation":"Der Händler schließt von der Herkunft („natürlich“) auf die Wirkung. Das ist ein Appell an die Natur. Ein Molekül ist durch seine Struktur bestimmt, nicht durch seinen Ursprung: Der Körper kann zwei identische Moleküle nicht unterscheiden. Eine bessere Wirkung müsste der Händler belegen, nicht behaupten. Das ist auch empirisch geprüft: Eine randomisierte Studie (Carr u. a. 2013) fand zwischen Vitamin C aus Kiwis und aus Tabletten keinen Unterschied in der Aufnahme. Was bleibt, ist der Preisaufschlag für ein Wort.","coreRule":"⚡ Gleiche Struktur, gleiche Wirkung: Die Herkunft eines Moleküls ist kein Qualitätsmerkmal; wer eine Überlegenheit behauptet, muss sie belegen.","beleg":"Werkstück D.4.3 (Der Vitamin-C-Test; Kontext & Tiefe); Fn. gl-d-vitc (Carr u. a. 2013, Nutrients 5(9), 3684–3695)","status":"entwurf","kurz":"Der Händler schließt von der Herkunft auf die Wirkung, doch ein Molekül ist durch seine Struktur bestimmt, nicht durch seinen Ursprung. Der Körper kann identische Moleküle nicht unterscheiden; eine bessere Wirkung müsste der Händler belegen.","prueffrage":"Was unterscheidet die beiden Pillen außer Herkunft und Preis?","rueckmeldung":[{"option":1,"text":"Handgepflückt klingt nach Sorgfalt und Qualität. Das betrifft aber die Ernte und sagt nichts darüber, wie das fertige Molekül im Körper wirkt; auch eine zutreffende Auskunft würde die Behauptung nicht stützen."},{"option":2,"text":"Ein Mengenvergleich wirkt sachlich und prüfbar. Er misst aber nur, wie viel enthalten ist, nicht ob die Herkunft etwas ändert. Mehr Milligramm wären ein anderer Vorteil als der behauptete."},{"option":3,"text":"Ein geschützter Begriff wirkt wie ein Gütesiegel. Er regelt aber, wie ein Produkt heißen darf, und nicht, wie es im Körper wirkt. Aus der Bezeichnung folgt daher nichts über die Wirkung."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carr, A. C. u. a. (2013): „A Randomized Steady-State Bioavailability Study of Synthetic versus Natural (Kiwifruit-Derived) Vitamin C“, Nutrients 5(9), 3684–3695 (DOI 10.3390/nu5093684)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2d913cecb66a8e2f"}},{"id":"qx-d2-038","clusterId":"D","werkstueckRef":"D.4.3","stufe":2,"question":"Was ist an diesem Werbeversprechen im Kern fehlerhaft?","scenario":"Auf einem Shampoo steht: „Frei von Chemie – rein natürlich.“ Ein Kollege sagt: „Dann ist es bestimmt sanfter und sicherer als die Konkurrenz.“","options":["Es setzt „Chemie“ mit „schädlich“ gleich: Weil das Shampoo „frei von Chemie“ und „rein natürlich“ ist, soll es sicherer sein, obwohl alle Stoffe Chemie sind und die Herkunft nichts über Sicherheit aussagt.","Es beruft sich auf Tradition: Weil sich Menschen seit Jahrhunderten mit Pflanzenstoffen die Haare waschen, soll dieses Shampoo bewährt sein, obwohl das Alter eines Brauchs nichts beweist.","Es beruft sich auf Autorität: Weil ungenannte Hautärzte das Shampoo angeblich empfehlen, soll es sicherer sein, obwohl das Ansehen von Befürwortern allein nichts über die Sicherheit aussagt.","Es schließt von der Beliebtheit auf die Sicherheit: Weil viele Käufer zu „rein natürlichen“ Shampoos greifen, soll dieses sanfter sein, obwohl Beliebtheit nichts über Verträglichkeit belegt."],"correctIndex":0,"explanation":"Alles ist Chemie: Ein Apfel ist ein Beutel voller Chemikalien, und auch Wasser (H₂O) ist Chemie. „Chemiefrei“ ist deshalb ein unmöglicher Zustand und als Eigenschaft eines Produkts bedeutungslos. Der Slogan arbeitet mit der Intuition, Natur sei gütig und das Labor kalt, und überspringt dabei die eigentlich entscheidenden Fragen: Welcher Stoff ist enthalten, in welcher Dosis, und was zeigen kontrollierte Studien zu Wirkung und Verträglichkeit? Die Herkunft eines Moleküls sagt darüber nichts. Ein identisches Molekül wirkt gleich, egal ob es aus einer Pflanze oder aus dem Labor stammt (bei Vitamin C aus Kiwis und aus Tabletten fand eine randomisierte Studie keinen Unterschied in der Aufnahme). Viele der giftigsten Substanzen der Welt sind „rein natürlich“, und synthetische Versionen sind oft reiner und genauer dosierbar. Die Werbung erzeugt also eine Präferenz, noch bevor ein einziges Faktum zur Sicherheit genannt wurde. Der Verweis auf Tradition klingt nach Erfahrung, doch der Slogan nennt keinen alten Brauch. Die Berufung auf Fachleute klingt nach Sachverstand, doch hier tritt niemand auf. Beliebtheit klingt nach Bewährung, doch zu Käuferzahlen sagt der Slogan nichts, er behauptet nur zwei Gleichungen.","coreRule":"⚡ „Chemiefrei“ gibt es nicht: Frag nach Stoff, Dosis und Studie – nicht nach der Herkunft.","beleg":"Werkstück D.4.3 (Kontext & Tiefe, „Alles ist chemisch“; Anwendung & Relevanz, Lebensmittel- und Kosmetikindustrie; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Der Slogan ist kaum mehr als ein Etikett: Alle Stoffe, auch Wasser, sind Chemie, und ob etwas sicher ist, entscheiden Stoff, Dosis und Studien, nicht seine Herkunft. „Natürlich“ bedeutet nicht automatisch „sanft“.","prueffrage":"Was erfährst du aus „Frei von Chemie – rein natürlich“ über die Inhaltsstoffe des Shampoos?","rueckmeldung":[{"option":1,"text":"Dass Pflanzen seit Langem zur Haarpflege dienen, würde tatsächlich noch nicht beweisen, dass sie sicher sind. Der Slogan nennt aber gar keinen alten Brauch, deshalb liegt der Fehler an anderer Stelle."},{"option":2,"text":"Ein Verweis auf Fachleute würde ein Produkt allein noch nicht sicher machen. Hier tritt aber niemand auf: Weder Hautärzte noch andere Experten werden erwähnt, der Slogan behauptet nur, das Produkt sei „natürlich“."},{"option":3,"text":"Beliebtheit sagt nichts über Verträglichkeit, das stimmt. Zu Käuferzahlen schweigt der Slogan jedoch, er stellt lediglich „Chemie“ und „Natur“ einander gegenüber. Der Fehler liegt in dieser Gleichsetzung."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carr, A. C. u. a. (2013): „A Randomized Steady-State Bioavailability Study of Synthetic versus Natural (Kiwifruit-Derived) Vitamin C“, Nutrients 5(9), 3684–3695 (DOI 10.3390/nu5093684)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1c8b6cc043f53118"}},{"id":"qx-d2-039","clusterId":"D","werkstueckRef":"D.4.3","stufe":3,"question":"Wo kippt eine harmlose Vorliebe für „Natürliches“ in eine echte Gefahr?","options":["Eine Person kauft bewusst weniger verarbeitete Lebensmittel, weil sie ihr besser schmecken und weil sie Zutatenlisten mit vielen Zusatzstoffen meidet.","Eine Person lehnt ein ärztlich empfohlenes, gut untersuchtes Medikament ab, weil es im Labor hergestellt wurde und „unnatürlich“ sei, und setzt stattdessen auf einen Kräutertee.","Eine Person greift zu einer Hautcreme mit Pflanzenextrakten, weil sie die Verpackung ansprechender findet als die der Konkurrenz.","Eine Person nimmt zusätzlich zur ärztlich verordneten Behandlung ein pflanzliches Mittel, weil sie sich damit besser fühlt und ihr Arzt davon weiß."],"correctIndex":1,"explanation":"Eine Vorliebe für weniger Verarbeitetes oder Pflanzliches bleibt harmlos, solange sie eine Geschmacks- oder Stilfrage ist. Gefährlich wird sie, wenn die Herkunft zum Maßstab wird und ein wirksames, gut geprüftes Mittel nur deshalb verworfen wird, weil es synthetisch ist. Ob ein Wirkstoff hilft oder schadet, hängt von Struktur, Dosis und belegter Wirkung ab, nicht davon, ob er im Labor oder in einer Pflanze entstand. Vitamin C aus Kiwis und aus Tabletten wird gleich gut aufgenommen. Wer aus „Natürlichkeit“ auf Sicherheit und aus „Labor“ auf Gefahr schließt, gibt im Ernstfall den Nutzen eines Medikaments, eines Impfstoffs oder eines lebensrettenden Zusatzstoffs auf. In den übrigen Fällen geht es um Geschmack, Verpackung oder eine Ergänzung in Absprache mit dem Arzt. Dort wird keine wirksame Behandlung verworfen.","coreRule":"⚡ Eine Vorliebe für Natürliches ist erlaubt; sie wird gefährlich, wenn sie wirksame Mittel verwirft.","beleg":"Werkstück D.4.3 (Der Kipppunkt)","status":"entwurf","scenario":"Vier Leute erzählen, wie sie es mit „natürlich“ und „synthetisch“ halten.","quote":"","quoteLabel":"","kurz":"Gefährlich wird die Vorliebe, wenn die Herkunft zum Maßstab wird und ein gut geprüftes Medikament nur abgelehnt wird, weil es synthetisch ist. Ob ein Stoff hilft oder schadet, hängt von Wirkstoff und Dosis ab, nicht davon, ob er aus Labor oder Pflanze stammt.","prueffrage":"Was steht für jede Person auf dem Spiel, falls sich ihre Wahl als falsch erweist?","rueckmeldung":[{"option":0,"text":"Weniger Verarbeitetes zu bevorzugen und Zutatenlisten mit vielen Zusatzstoffen zu meiden, ist eine Geschmacks- und Stilfrage. Dabei wird keine wirksame Behandlung aufgegeben und auf keine nötige Hilfe verzichtet."},{"option":2,"text":"Eine Creme wegen der Verpackung zu wählen, ist eine reine Geschmacksentscheidung ohne Urteil über Gesundheit. Es wird nichts abgelehnt, was helfen könnte; die Herkunft ist hier nicht der Maßstab."},{"option":3,"text":"Ein pflanzliches Mittel neben einer Therapie wirkt riskant, und Wechselwirkungen kommen tatsächlich vor. Hier läuft die verordnete Behandlung aber weiter, und der Arzt weiß davon. Verworfen wird keine wirksame Therapie."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Carr, A. C. u. a. (2013): „A Randomized Steady-State Bioavailability Study of Synthetic versus Natural (Kiwifruit-Derived) Vitamin C“, Nutrients 5(9), 3684–3695 (DOI 10.3390/nu5093684)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"22288620dc3acd5e"}},{"id":"qx-d2-040","clusterId":"D","werkstueckRef":"D.4.3","stufe":4,"question":"Welche Erklärung für die Streifen vom Donnerstag ist die sparsamste und lässt sich zugleich am besten prüfen?","scenario":"In einem Video heißt es, Flugzeuge versprühten „Chemtrails“: Lang stehende weiße Streifen am Himmel seien künstliche Gifte. Dein Nachbar hat notiert: Am Dienstag lösten sich die Streifen nach wenigen Sekunden auf, am Donnerstag blieben sie stundenlang stehen und breiteten sich aus. Laut Wetterdaten war die Luft in Reiseflughöhe am Dienstag trocken, am Donnerstag sehr feucht und kalt.","options":["Ein Zusatzstoff in den Abgasen hielt die Streifen am Donnerstag länger; prüfen lässt sich das, sobald jemand an einem solchen Tag eine Bodenprobe nimmt und den Stoff findet.","Am Donnerstag flogen andere Maschinen mit giftiger Fracht als am Dienstag; prüfen lässt sich das, wenn man die Flugrouten beider Tage nebeneinanderlegt und vergleicht.","Ein verdecktes Sprühprogramm nutzte die Wetterlage am Donnerstag als Tarnung; prüfen ließe sich das erst, wenn die Beteiligten ihre Unterlagen freiwillig offenlegten.","Eiskristalle aus dem Wasserdampf der Abgase hielten sich am Donnerstag in der feuchten Kaltluft; prüfen lässt sich das an weiteren Tagen mit bekannten Feuchtewerten."],"correctIndex":3,"explanation":"Die sparsamste Erklärung kommt mit bekannten Vorgängen aus: Die Streifen sind gewöhnliche Kondensstreifen, also Eiskristalle aus dem Wasserdampf der Triebwerksabgase. Wie lange sie stehen bleiben und ob sie sich ausbreiten, hängt von Feuchte und Temperatur der Luft in Flughöhe ab: In sehr feuchter, kalter Luft halten sie sich lange, in trockener verschwinden sie rasch. Genau das zeigen die Notizen des Nachbarn: rasches Verschwinden am trockenen Dienstag, langes Stehen am feuchten, kalten Donnerstag. Diese Erklärung macht eine Vorhersage, die jeder an weiteren Tagen überprüfen kann. Zusatzstoff, giftige Fracht und Sprühprogramm klingen nach Prüfbarkeit, führen aber unbelegte Stoffe oder Absichten ein, die der Unterschied zwischen den beiden Tagen gar nicht verlangt, weil die Wetterlage ihn schon erklärt. Die Tarnungsdeutung ist zudem so gebaut, dass sie sich nie widerlegen lässt, solange niemand Unterlagen herausgibt. „Künstlich“ ist kein Beweis für „giftig“: Wer ein Gift behauptet, muss Stoff, Menge und Beleg nennen.","coreRule":"⚡ „Künstlich“ ist kein Beweis für „giftig“: Frage nach Stoff, Menge und Beleg, nicht nach der Herkunft.","beleg":"Werkstück D.4.3 (Anwendung & Relevanz, „Bei Verschwörungsmythen (Chemtrails etc.)“)","status":"entwurf","kurz":"Der Unterschied zwischen beiden Tagen liegt in der Luftfeuchte und Kälte in Flughöhe. Die Streifen sind gewöhnliche Kondensstreifen, und das Wetter erklärt ihr Verhalten. Zusätzliche Stoffe oder Absichten braucht es dafür nicht.","prueffrage":"Was unterscheidet die beiden Tage außer dem Aussehen der Streifen, und könnte schon das den Unterschied erklären?","rueckmeldung":[{"option":0,"text":"Eine Bodenprobe klingt nach sauberer Prüfung. Doch ein unbelegter Zusatzstoff wird erst eingeführt, obwohl das Wetter den Tagesunterschied schon erklärt, und ohne einen konkret benannten Stoff weiß man nicht, wonach man suchen soll."},{"option":1,"text":"Einen Routenvergleich kann man tatsächlich anstellen. Er zeigt aber nur, wo geflogen wurde, nicht was ausgestoßen wurde, und die „giftige Fracht“ ist ohne Beleg dazugedacht, obwohl die Wetterlage den Unterschied bereits erklärt."},{"option":2,"text":"Die Wetterlage als Tarnung zu deuten, wirkt wie eine Erklärung, die alles abdeckt. Genau das ist das Problem: Sie lässt sich nur prüfen, wenn Beteiligte Unterlagen herausgeben, und ohne diese nie widerlegen. Nötig ist sie ohnehin nicht, denn das Wetter genügt."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): „Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program“, Environ. Res. Lett. 11, 084011","oeffentlich":true,"doi":"10.1088/1748-9326/11/8/084011","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schumann, U. (1996): „On conditions for contrail formation from aircraft exhausts“, Meteorologische Zeitschrift 5(1), 4–23","oeffentlich":true,"doi":"10.1127/metz/5/1996/4","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"de49f6f46761e82d"}},{"id":"qx-d2-041","clusterId":"D","werkstueckRef":"D.4.4","stufe":1,"question":"Wie lässt sich der Unterschied zwischen den beiden Ansätzen am besten beschreiben, obwohl beide „ganzheitlich“ sagen?","scenario":"Du hast chronische Kopfschmerzen. Arzt A untersucht dich gründlich, verschreibt ein Medikament und fragt auch nach Stress, Schlaf und Ernährung. Arzt B untersucht dich nicht körperlich, spricht von einer „Blockade im Energie-Meridian“ und verkauft dir Kristalle. Beide nennen ihren Ansatz „ganzheitlich“.","options":["Arzt A erweitert die überprüfbare Medizin um Lebensstil und Psyche; Arzt B ersetzt sie durch Konzepte, die sich nicht messen lassen.","Arzt A behandelt nur das Symptom, während Arzt B den ganzen Menschen betrachtet und damit als Einziger wirklich ganzheitlich arbeitet.","Beide arbeiten gleichermaßen ganzheitlich; Arzt B ist nur weniger genau und könnte seine Methoden durch Messungen ergänzen.","Arzt A arbeitet ganzheitlich, weil er ein Medikament verschreibt; Arzt B nicht, weil er Körper und Geist als getrennte Bereiche behandelt."],"correctIndex":0,"explanation":"Dass Körper, Geist und Umwelt zusammenhängen, ist unstrittig und in der Medizin etabliert: Die Psychoneuroimmunologie erforscht zum Beispiel, wie Stress das Immunsystem beeinflusst. Arzt A nutzt diesen Gedanken, um eine geprüfte Behandlung zu ergänzen. Arzt B nutzt dieselbe unstrittige Aussage als Eintrittskarte für Diagnosen und Behandlungen, die sich nicht überprüfen lassen. Dass das Wort gleich klingt, sagt nichts darüber, was damit verkauft wird: Wer dem Grundsatz „Körper und Geist sind verbunden“ zustimmt, hat damit noch nicht Kristalle oder Meridian-Blockaden als wirksam anerkannt.","coreRule":"⚡ „Ganzheitlich“ kann ergänzen oder ersetzen: Prüf, was damit verkauft wird.","beleg":"Werkstück D.4.4 (Die zwei Ärzte; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Beide berufen sich auf den unstrittigen Gedanken, dass Körper und Psyche zusammenhängen. Arzt A ergänzt damit geprüfte Medizin, Arzt B verkauft Unüberprüfbares. Das gleiche Wort sagt nichts darüber, was dahintersteckt.","prueffrage":"Was hat jeder der beiden Ärzte getan, bevor er seine Behandlung festgelegt hat?","rueckmeldung":[{"option":1,"text":"Ein Medikament wirkt schnell wie reine Symptombehandlung. Doch Arzt A untersucht gründlich und fragt nach Stress, Schlaf und Ernährung, während Arzt B nicht einmal körperlich untersucht und den Menschen damit kaum umfassender betrachtet."},{"option":2,"text":"Weil beide dasselbe Wort benutzen, wirken die Ansätze gleichwertig. Arzt B ergänzt aber keine geprüfte Medizin, er ersetzt sie durch Konzepte wie Meridian-Blockaden, die sich nicht messen lassen. Das ist kein Unterschied im Grad der Genauigkeit."},{"option":3,"text":"Ein Medikament macht eine Behandlung nicht ganzheitlich; bei Arzt A zählt, dass er auch Stress, Schlaf und Ernährung einbezieht. Arzt B trennt Körper und Geist gar nicht, sein Problem ist die fehlende Überprüfbarkeit."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Segerstrom, S. C.; Miller, G. E. (2004): „Psychological Stress and the Human Immune System: A Meta-Analytic Study of 30 Years of Inquiry“, Psychological Bulletin 130(4), 601–630","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1361287/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"62695620594fbc98"}},{"id":"qx-d2-042","clusterId":"D","werkstueckRef":"D.4.4","stufe":2,"question":"Was ist an dieser Abfolge von Aussage und Schlussfolgerung fehlerhaft?","scenario":"Auf einer Website steht: „Wir betrachten den ganzen Menschen, denn Körper und Geist sind untrennbar verbunden. Deshalb gleichen wir mit unserer Aura-Reinigung Ihre Energiefelder aus.“","options":["Die erste Aussage ist unstrittig. Weil ihr niemand widerspricht, wird stillschweigend auch die darauf aufbauende, unbewiesene Methode als akzeptiert behandelt.","Die erste Aussage zeichnet eine übertriebene Karikatur der Gegenseite, die sich leicht widerlegen lässt und die eigene Methode dadurch stärker wirken lässt.","Die erste Aussage beruft sich auf anerkannte medizinische Autoritäten, und die Fachsprache wird dann auf fremde Verfahren übertragen, ohne deren Wirkung zu belegen.","Die erste Aussage stellt zwei Wege als einzige Möglichkeiten dar, nämlich ganzheitlich oder nur Symptome behandeln, und verschweigt weitere Alternativen."],"correctIndex":0,"explanation":"Der Text beginnt mit einer Binsenweisheit: Körper und Geist hängen zusammen, das ist auch wissenschaftlich anerkannt. Das „Deshalb“ tut so, als folge die Wirksamkeit der Aura-Reinigung zwangsläufig daraus. Das tut sie nicht. Dass alles verbunden ist, sagt nichts darüber, ob ein bestimmtes Verfahren eine messbare Wirkung hat. Das ist der Motte-and-Bailey-Trick: Die unstrittige „Motte“ (Körper und Geist sind verbunden) dient als Brücke zur umstrittenen „Bailey“ (meine Methode wirkt). Eine Karikatur der Gegenseite, eine Berufung auf Autoritäten oder ein falsches Entweder-oder kommen im Text nicht vor. Er arbeitet allein mit der unstrittigen Vorbehauptung und dem „Deshalb“. Eine gute Prüffrage lautet: Welchen konkreten, überprüfbaren Beleg gibt es für die Methode selbst, über den bloßen Placebo-Effekt hinaus?","coreRule":"⚡ Trenne die wahre Aussage von der Methode, die dahinter verkauft wird.","beleg":"Werkstück D.4.4 (Kontext & Tiefe, Motte-and-Bailey; Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Der Satz über Körper und Geist ist anerkannt, doch aus ihm folgt nicht, dass eine bestimmte Methode wirkt. Das „Deshalb“ nutzt die unstrittige Aussage als Brücke zur umstrittenen Behauptung, die damit nicht belegt ist.","prueffrage":"Welche andere Behandlung ließe sich mit dem ersten Satz der Website genauso gut begründen?","rueckmeldung":[{"option":1,"text":"Eine Gegenseite taucht im Text gar nicht auf, also wird auch nichts verzerrt oder leicht widerlegt. Der Text stützt seine Methode allein auf eine Aussage, der kaum jemand widerspricht."},{"option":2,"text":"Autoritäten werden hier nicht angeführt: Der Text nennt weder Fachleute noch Institute, sondern äußert nur eine allgemein anerkannte Einsicht. Das Problem liegt im „Deshalb“, nicht in geliehenem Ansehen."},{"option":3,"text":"Ein Entweder-oder fehlt im Text. Er stellt keine zwei Wege gegenüber und lässt auch nichts Bestimmtes aus. Die Lücke liegt zwischen der unstrittigen Aussage und der Methode, die daraus abgeleitet wird."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Shackel, N. (2005): „The Vacuity of Postmodernist Methodology“, Metaphilosophy 36(3), 295–320 (DOI 10.1111/j.1467-9973.2005.00370.x)","oeffentlich":false},{"typ":"url","kurz":"Segerstrom, S. C.; Miller, G. E. (2004): „Psychological Stress and the Human Immune System“, Psychological Bulletin 130(4), 601–630","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1361287/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"59878285220f6760"}},{"id":"qx-d2-043","clusterId":"D","werkstueckRef":"D.4.4","stufe":3,"question":"Eine Bekannte erzählt dir: „Ich lasse mich jetzt nur noch ‚ganzheitlich‘ behandeln. Meine Heilerin sagt, mein Knoten in der Brust ist eine Energieblockade und braucht keine Untersuchung.“ Woran wird hier das Problem am klarsten sichtbar?","options":["Die Heilerin beruft sich auf die alte Energielehre von Blockaden im Körper, obwohl ein Verfahren, das seit Jahrhunderten bekannt ist, deshalb nicht erklärt, was der Knoten ist.","Die Heilerin macht aus der richtigen Idee „Körper und Geist hängen zusammen“ die Begründung, den Knoten in der Brust nicht abklären zu lassen, obwohl er ernst sein könnte.","Die Bekannte schließt aus dem Wohlgefühl nach den Sitzungen bei der Heilerin auf die Wirkung der Methode, obwohl ein einzelnes Gefühl nichts über den Knoten belegt.","Die Heilerin verspricht, dass sich der Knoten durch die Behandlung auflöst, obwohl seriöse Anbieter keinen Heilerfolg zusichern, weil kein Verfahren bei allen gleich wirkt."],"correctIndex":1,"explanation":"Dass Körper, Psyche und Lebensumstände zusammenhängen, ist unstrittig und gehört zur guten Medizin. Gefährlich wird „ganzheitlich“ erst dort, wo die Zustimmung zu dieser harmlosen Aussage als Freibrief dient, eine konkrete, unbewiesene Methode anzuwenden und dafür eine mögliche ernste Erkrankung nicht untersuchen oder behandeln zu lassen. Entscheidend ist die Folge: Eine nötige, wirksame Abklärung unterbleibt. Ergänzende Verfahren neben der Behandlung sind meist unproblematisch, solange die behandelnde Ärztin davon weiß. Die alte Energielehre klingt nach Erfahrung, doch auf ihr Alter stützt sich die Heilerin hier gar nicht. Das Wohlgefühl nach Sitzungen klingt nach Erfolg, doch von Sitzungen oder Erfolgen ist nirgends die Rede. Ein Heilversprechen wäre ein Warnzeichen, doch zugesagt wird hier nichts, sie lässt nur die Untersuchung weg.","coreRule":"⚡ Die Grenze verläuft dort, wo aus einer wahren Binsenweisheit der Verzicht auf wirksame Behandlung abgeleitet wird.","beleg":"Werkstück D.4.4 (Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Hier wird nicht die Verbindung von Körper und Psyche zum Problem, sondern was daraus folgt: Der Knoten wird nicht abgeklärt, obwohl er ernst sein könnte. „Ganzheitlich“ klingt harmlos, wird aber zum Freibrief für das Weglassen der Untersuchung.","prueffrage":"Was genau ändert sich für die Bekannte durch den Rat der Heilerin, verglichen mit dem, was sie sonst getan hätte?","rueckmeldung":[{"option":0,"text":"Dass etwas lange bekannt ist, beweist wenig, und eine „Blockade“ sagt nicht, was der Knoten ist. Auf ein hohes Alter ihrer Lehre stützt sich die Heilerin hier aber gar nicht, das Problem liegt woanders."},{"option":2,"text":"Ein gutes Gefühl nach einer Behandlung sagt tatsächlich nichts über einen Knoten. Von Sitzungen oder einem Wohlgefühl ist hier aber nirgends die Rede; das Problem liegt bei dem, was weggelassen wird."},{"option":3,"text":"Ein Heilversprechen wäre ein Warnzeichen, und kein Verfahren wirkt bei allen gleich. Zugesagt wird hier aber nichts: Die Heilerin lässt nur die Untersuchung weg, und darin liegt die Gefahr."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Johnson, S. B.; Park, H. S.; Gross, C. P.; Yu, J. B. (2018): „Use of Alternative Medicine for Cancer and Its Impact on Survival“, JNCI 110(1), 121–124 (Volltext Bezahlschranke, Abstract frei)","oeffentlich":true,"doi":"10.1093/jnci/djx145","abruf":"2026-10-12"},{"typ":"url","kurz":"Segerstrom, S. C.; Miller, G. E. (2004): „Psychological Stress and the Human Immune System“, Psychological Bulletin 130(4), 601–630","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1361287/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"66fe6557bf52ace6"}},{"id":"qx-d2-044","clusterId":"D","werkstueckRef":"D.4.5","stufe":1,"question":"Ein Coach sagt: „Das Gesetz der Anziehung ist so unumstößlich wie die Schwerkraft. Wenn dein Wunsch nicht eintrifft, hast du es falsch angewendet.“ Du sollst herausfinden, ob das wirklich ein Gesetz im Sinne der Naturwissenschaft ist. Welche Prüffrage deckt das Problem am besten auf?","options":["Wer verdient an den Büchern und Seminaren des Coaches zum Gesetz?","Welches Ergebnis würde das Gesetz der Anziehung eindeutig widerlegen?","Gibt es Zuhörer, bei denen das Gesetz der Anziehung geklappt hat?","Hat der Coach in früheren Vorträgen schon Falsches behauptet?"],"correctIndex":1,"explanation":"Ein Naturgesetz wie die Schwerkraft beschreibt, was beobachtbar geschieht, und ist falsifizierbar: Würde ein losgelassener Apfel zur Decke schweben, wäre das Gesetz widerlegt. Beim „Gesetz der Anziehung“ ist es umgekehrt: Es ist unfalsifizierbar. Bleibt der Wunsch unerfüllt, liegt die Schuld immer beim Anwender, nie beim „Gesetz“. Die Frage nach dem widerlegenden Ergebnis trifft genau diesen Punkt. Die Frage nach dem Verdienst klingt nach einer Prüfung auf Befangenheit, sagt aber etwas über Interessen und nichts über Gültigkeit. Berichte gelungener Fälle klingen nach Belegen, lassen sich bei einer Regel, die jeden Misserfolg erklärt, aber immer finden. Frühere Irrtümer des Coaches klingen nach mangelnder Glaubwürdigkeit, ändern jedoch nichts daran, dass die Behauptung selbst auf ihre Prüfbarkeit hin untersucht werden muss.","coreRule":"⚡ Ein „Gesetz“, das nie scheitern kann, ist kein Naturgesetz: Frag, welches Ergebnis es widerlegen würde.","beleg":"Werkstück D.4.5 (Die zwei Gesetze; Kontext & Tiefe)","status":"entwurf","scenario":"Ein Coach erklärt in einem Vortrag: „Das Gesetz der Anziehung wirkt immer. Wer Reichtum aussendet, bekommt Reichtum. Wenn es bei dir nicht klappt, waren deine Gedanken nicht klar genug oder du hattest unbewusste Blockaden.“","kurz":"Ein Gesetz wie die Schwerkraft lässt sich widerlegen, etwa durch einen Apfel, der zur Decke schwebt. Beim „Gesetz der Anziehung“ liegt die Schuld bei jedem Misserfolg beim Anwender, also kann nichts es widerlegen. Genau das macht es unprüfbar.","prueffrage":"Wie erklärt der Coach einen Wunsch, der eintrifft, und wie einen, der ausbleibt?","rueckmeldung":[{"option":0,"text":"Wer an einer Behauptung verdient, hat ein Interesse, und das darf Skepsis wecken. Ob die Behauptung gilt, hängt aber nicht davon ab, wer von ihr profitiert, sondern davon, ob sie sich prüfen lässt."},{"option":2,"text":"Berichte von gelungenen Fällen wirken wie Belege. Bei einer Regel, die jeden Misserfolg dem Anwender zuschreibt, finden sich solche Fälle aber immer, und sie sagen nichts darüber, ob die Regel überhaupt prüfbar ist."},{"option":3,"text":"Frühere Irrtümer können das Vertrauen in einen Redner mindern. Die aktuelle Behauptung bleibt davon aber unberührt: Sie muss selbst darauf untersucht werden, ob sich überhaupt etwas finden ließe, das sie widerlegt."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"bd1121482ce79935"}},{"id":"qx-d2-045","clusterId":"D","werkstueckRef":"D.4.5","stufe":2,"question":"Was ist an dieser Erklärung des Coaches das Problem?","scenario":"Du hast drei Monate lang jeden Morgen positiv gedacht, wie dein Coach es nach dem „Gesetz der Anziehung“ verlangt hat, und bist nicht reicher geworden. Der Coach sagt: „Das Gesetz wirkt so zuverlässig wie die Schwerkraft. Wenn sich nichts getan hat, hast du unbewusst negativ gedacht.“","options":["Der Coach lastet das Ausbleiben des Reichtums dem Anwender an: Weil so nie das Gesetz schuld ist, kann nichts es widerlegen, obwohl eine prüfbare Behauptung scheitern können muss.","Der Coach beruft sich auf Autorität: Weil bekannte Lehrer und Bestsellerautoren das Gesetz der Anziehung vertreten, soll es so zuverlässig sein wie die Schwerkraft, obwohl der Name eines Lehrers keinen Beleg ersetzt.","Der Coach verallgemeinert aus Erfolgsgeschichten: Weil frühere Kunden nach dem Morgendenken reicher wurden, soll das Gesetz für alle gelten, obwohl wenige Fälle keine allgemeine Regel belegen.","Der Coach hält ein bloßes Nacheinander für Ursache: Weil Wohlstand nach positivem Denken kam, soll das Denken ihn bewirkt haben, obwohl beides zufällig zusammenfallen kann."],"correctIndex":0,"explanation":"Eine Behauptung ist nur dann prüfbar, wenn sie scheitern kann. Hier ist das ausgeschlossen: Tritt der Wunsch ein, gilt das als Beweis. Tritt er nicht ein, war angeblich der Glaube nicht stark genug oder es gab unbewusste Blockaden. Damit liegt die Schuld immer beim Anwender und nie bei der Behauptung, und kein denkbares Ergebnis könnte sie widerlegen. Bei der Schwerkraft ist das anders: Schwebte ein losgelassener Apfel zur Decke, wäre sie widerlegt, egal ob jemand daran glaubt. Wer das Scheitern grundsätzlich dem Menschen zuschreibt, schützt seine Behauptung vor jeder Kritik und beschuldigt zugleich die Betroffenen. Außerdem wertet man dann jeden Erfolg als Bestätigung und jeden Misserfolg als eigenes Versagen, was den Bestätigungsfehler verschärft.","coreRule":"⚡ Wenn nur der Anwender scheitern kann, nie die Behauptung, ist es keine Prüfung.","beleg":"Werkstück D.4.5 (Kontext & Tiefe; Der Kipppunkt; Verbindungen)","status":"entwurf","kurz":"Wenn jeder Misserfolg als „unbewusst negatives Denken“ gilt, kann kein Ergebnis das Gesetz widerlegen. Eine prüfbare Behauptung muss scheitern können. Die Schwerkraft kann das: Schwebte der Apfel nach oben, wäre sie widerlegt, egal woran jemand glaubt.","prueffrage":"Wie hätte der Coach es gedeutet, wenn du nach drei Monaten reicher geworden wärst?","rueckmeldung":[{"option":1,"text":"Ein bekannter Name klingt nach Sachverstand, und ein Name ersetzt tatsächlich keinen Beleg. Der Coach nennt hier aber keinen Lehrer oder Autor. Sein Fehler liegt woanders: Er erklärt das Ausbleiben des Erfolgs so, dass nichts das Gesetz widerlegen kann."},{"option":2,"text":"Erfolgsgeschichten wirken wie Belege, und wenige Fälle begründen tatsächlich keine allgemeine Regel. Der Coach nennt hier aber keine früheren Kunden oder Erfolge. Dein Fall zeigt das Gegenteil, und der Coach deutet ihn zu deinem Versagen um."},{"option":3,"text":"Aus einem bloßen Nacheinander eine Ursache zu machen, ist ein typischer Fehler. Hier gab es aber gar keinen Reichtum, der auf das positive Denken gefolgt wäre. Der Coach schließt nicht aus der Zeitfolge, sondern erklärt das Ausbleiben so, dass es das Gesetz nie widerlegt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"0cff78b5b712ee51"}},{"id":"qx-d2-046","clusterId":"D","werkstueckRef":"D.4.5","stufe":3,"question":"Welcher Umgang mit einem solchen Gesetz entspricht dem Prinzip der Falsifizierbarkeit am besten?","options":["Die Wissenschaft sammelt weitere Messungen bei alltäglichen Geschwindigkeiten, wo Newtons Mechanik stimmt, denn viele Bestätigungen wiegen die Abweichungen bei hohen Geschwindigkeiten auf.","Die Wissenschaft ersetzt Newtons Mechanik durch eine genauere Theorie, die sie bei kleinen Geschwindigkeiten als Näherung enthält und die Abweichungen bei hohen Geschwindigkeiten miterklärt.","Die Wissenschaft ergänzt Newtons Mechanik um Zusatzannahmen, die nichts anderes leisten, als die Abweichungen bei hohen Geschwindigkeiten zu erklären, und behält sie ansonsten bei.","Die Wissenschaft lässt die Fachwelt abstimmen und gibt Newtons Mechanik erst auf, wenn die Mehrheit der Physiker sich gegen sie ausspricht, weil Abweichungen sie noch nicht widerlegen."],"correctIndex":1,"explanation":"Ein wissenschaftliches Gesetz ist falsifizierbar: Eine Beobachtung, die ihm widerspricht, zählt als Gegenbeleg. Stößt es nachweislich an Grenzen, ist der beste Ausgang eine genauere Theorie, die alles erklärt, was das alte Gesetz erklärt hat, und dazu die Abweichungen – so löste die Relativitätstheorie Newtons Mechanik ab, die im Alltag als sehr gute Näherung weiter dient. Der Gesprächspartner übersieht diese Möglichkeit zwischen „ausnahmslos wahr“ und „wegwerfen“. Weitere Bestätigungen bei Alltagsgeschwindigkeiten klingen nach Absicherung, heben eine nachgewiesene Abweichung aber nicht auf. Zusatzannahmen klingen nach Verbesserung, machen das Gesetz aber unwiderlegbar, wenn sie nur die Abweichungen wegerklären. Eine Abstimmung klingt demokratisch, doch über die Geltung entscheidet die Beobachtung, nicht die Mehrheit der Fachleute.","coreRule":"⚡ Ein echtes Gesetz darf scheitern und wird dann durch eine genauere Theorie ersetzt. Wer Misserfolge stets dem Anwender oder neuen Ausnahmen zuschreibt, schützt einen Glaubenssatz.","beleg":"Werkstück D.4.5 (Kontext & Tiefe, „Ein wissenschaftliches Gesetz“; Verweis A.20)","status":"entwurf","scenario":"Ein Gesprächspartner sagt: „Ein Gesetz, das irgendwo nachweislich danebenliegt, ist wertlos. Entweder es stimmt ausnahmslos, oder man kann es wegwerfen.“ Du sollst beurteilen, wie die Wissenschaft mit einem Gesetz umgeht, das nachweislich an Grenzen stößt – etwa Newtons Mechanik bei sehr hohen Geschwindigkeiten.","kurz":"Eine nachgewiesene Abweichung ist ein Gegenbeleg, ohne dass das Gesetz damit wertlos wird. Die Falle liegt im Entweder-oder: Es gibt den Mittelweg einer genaueren Theorie, die das Alte als Näherung enthält und die Abweichungen miterklärt.","prueffrage":"Gilt Newtons Mechanik im Alltag weiterhin zuverlässig, und wo genau beginnen die Abweichungen?","rueckmeldung":[{"option":0,"text":"Im Alltagsbereich stimmt Newtons Mechanik tatsächlich sehr gut, das spricht für ihre Brauchbarkeit. Eine nachgewiesene Abweichung bei hohen Geschwindigkeiten gleichen weitere Treffer dort aber nicht aus: Sie bleibt ein Gegenbeleg."},{"option":2,"text":"Zusatzannahmen können sinnvoll sein, wenn sie mehr erklären als nur die Abweichung. Hier leisten sie nichts anderes, als diese wegzuerklären, und genau dadurch würde das Gesetz unwiderlegbar, also nicht mehr prüfbar."},{"option":3,"text":"Eine Abstimmung wirkt fair und gemeinsam getragen. Über die Geltung eines Gesetzes entscheidet aber die Beobachtung, nicht die Mehrheit; eine nachgewiesene Abweichung verschwindet nicht, weil viele Fachleute am Gesetz festhalten."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"995e32a7228a6ce0"}},{"id":"qx-d2-047","clusterId":"D","werkstueckRef":"D.4.5","stufe":4,"question":"Der Heilpraktiker sagt: „Meine Methode folgt fünf biologischen Naturgesetzen. Wenn eine Behandlung nicht anschlägt, haben Patienten das Gesetz nicht richtig befolgt.“ Was ist an dieser Rechtfertigung am problematischsten?","options":["Er nennt seine Methode „fünf biologische Naturgesetze“ und leiht ihr damit die Autorität echter Gesetze, obwohl sie weder prüfbar noch widerlegbar ist.","Er beruft sich auf eine lange Heiltradition hinter den „fünf biologischen Naturgesetzen“, obwohl das Alter einer Methode nichts über ihre Wirkung sagt.","Er stützt die „fünf biologischen Naturgesetze“ auf Berichte zufriedener Patienten seiner Praxis, obwohl einzelne Berichte keine Wirksamkeit belegen.","Er verspricht Patienten Heilung nach den „fünf biologischen Naturgesetzen“ binnen weniger Tage, obwohl kein Verfahren bei allen gleich schnell wirkt."],"correctIndex":0,"explanation":"Ein echtes Naturgesetz beschreibt, was geschieht, macht überprüfbare Vorhersagen und wäre durch ein gegenteiliges Ergebnis widerlegt. Die Methode des Heilpraktikers erfüllt nichts davon: Er nennt keine Prüfung, und jedes Scheitern wird dem Patienten angelastet, sodass nichts sie je widerlegen könnte. Das Wort „Naturgesetz“ erzeugt hier nur den Anschein von Notwendigkeit und Wissenschaftlichkeit. Ein Anspruch dieser Art muss sich an denselben Maßstäben messen lassen wie ein echtes Gesetz: Was sagt er voraus, und was würde ihn widerlegen?","coreRule":"⚡ Wer „Naturgesetz“ sagt, muss Vorhersage und Widerlegbarkeit liefern.","beleg":"Werkstück D.4.5 (Anwendung & Relevanz, „In der Pseudomedizin“; Kernidee)","status":"entwurf","scenario":"Ein Heilpraktiker wirbt für ein Therapiekonzept, das er nie in Studien geprüft hat. Auf Nachfrage verweist er auf „fünf biologische Naturgesetze“. Ein Patient, dem die Behandlung nicht geholfen hat, soll laut ihm selbst schuld sein.","kurz":"Das Wort „Naturgesetz“ klingt nach Notwendigkeit, doch ein echtes Gesetz sagt Prüfbares voraus und ließe sich widerlegen. Hier wird jedes Scheitern dem Patienten angelastet, sodass nichts die Methode je widerlegen könnte.","prueffrage":"Welche Prüfung seiner Methode nennt der Heilpraktiker, und wie erklärt er den Fall eines Patienten, dem sie nicht geholfen hat?","rueckmeldung":[{"option":1,"text":"Dass das Alter einer Methode nichts über ihre Wirkung sagt, stimmt. Der Heilpraktiker beruft sich im Szenario aber auf keine Tradition, sondern auf „Naturgesetze“. Das Problem liegt also in diesem Wort und nicht in einem Erfahrungsargument."},{"option":2,"text":"Einzelne Berichte zufriedener Patienten würden tatsächlich keine Wirksamkeit belegen. Der Heilpraktiker führt aber keine an, es fehlt jede Art von Beleg. Der Schwachpunkt liegt woanders: Seine Rechtfertigung ist gar nicht prüfbar."},{"option":3,"text":"Schnelle Heilungsversprechen wären tatsächlich ein Warnzeichen, denn kein Verfahren wirkt bei allen gleich schnell. Eine solche Zusage macht der Heilpraktiker hier aber nicht. Das eigentliche Problem liegt in der Rechtfertigung selbst."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8f9e09e33007ac33"}}]`);export{t as n,n as t};